import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu from './components/Menu';
import Hud, { Toast } from './components/Hud';
import { PauseMenu, Results } from './components/Overlays';
import { Game, HudState, RaceResult } from './game/engine';
import { diffById, loadSave, SaveData, storeSave, themeById, TOTAL_LAPS } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const EMPTY_HUD: HudState = {
  pos: 6, total: 6, lap: 1, laps: TOTAL_LAPS, time: 0, lapTime: 0, bestLap: Infinity, kmh: 0, speedN: 0,
  item: null, rolling: false, boost: 0, shield: 0, drift: 0, countdown: '3', wrong: false, mode: 'countdown',
};

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu'), screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY_HUD);
  const [save, setSave] = useState<SaveData>(() => loadSave()), saveRef = useRef(save);
  const [result, setResult] = useState<{ r: RaceResult; record: boolean } | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]), toastId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onEvent: (text, color) => {
        const id = ++toastId.current;
        setToasts(t => [...t.slice(-2), { id, text, color }]);
        timers.current.push(window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 1400));
      },
      onFinish: r => {
        const prev = saveRef.current, tid = prev.track;
        const record = !prev.best[tid] || r.time < (prev.best[tid] ?? Infinity);
        persist({
          ...prev,
          best: { ...prev.best, [tid]: Math.min(prev.best[tid] ?? Infinity, r.time) },
          bestPos: { ...prev.bestPos, [tid]: Math.min(prev.bestPos[tid] ?? 99, r.pos) },
          wins: prev.wins + (r.pos === 1 ? 1 : 0),
        });
        setResult({ r, record }); go('over');
        if (r.pos <= 3 || record) {
          try { confetti({ particleCount: 160, spread: 100, origin: { y: 0.35 }, colors: ['#ff2d3d', '#ffd23f', '#2f7bff', '#22c55e'] }); } catch { /* sin confeti */ }
        }
      },
    });
    game.toAttract(themeById(saveRef.current.track));
    gameRef.current = game;
    return () => { timers.current.forEach(t => window.clearTimeout(t)); timers.current = []; game.dispose(); gameRef.current = null; };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init();
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setResult(null); setHud(EMPTY_HUD);
    g.newRace(themeById(saveRef.current.track), diffById(saveRef.current.diff));
    go('play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract(themeById(saveRef.current.track)); setToasts([]); go('menu');
  }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p); go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      if (screenRef.current === 'play') setPaused(true); else if (screenRef.current === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };
  const mapRef = useCallback((c: HTMLCanvasElement | null) => { gameRef.current?.attachMinimap(c); }, []);

  return (
    <div className="kr-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#cfe7ff]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="kr-vignette absolute inset-0" />

      {screen === 'menu' && (
        <Menu save={save} muted={muted} onMute={toggleMute} onPlay={start}
          onTrack={id => { sound.click(); persist({ ...saveRef.current, track: id }); gameRef.current?.toAttract(themeById(id)); }}
          onDiff={id => { sound.click(); persist({ ...saveRef.current, diff: id }); }} />
      )}

      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} pad={gameRef.current.input.virtual}
          mapRef={mapRef} onPause={() => setPaused(true)} onMute={toggleMute} />
      )}

      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}

      {screen === 'over' && result && (
        <Results r={result.r} record={result.record} trackName={themeById(save.track).name} best={save.best[save.track] ?? 0}
          onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { ArrowDown, ArrowUp, Banana, ChevronLeft, ChevronRight, Flame, Pause, Shield, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import { formatTime, ItemId, ITEM_INFO } from '../game/config';
import { HudState } from '../game/engine';
import { VirtualPad } from '../game/input';

export interface Toast { id: number; text: string; color: string }

interface Props {
  hud: HudState; toasts: Toast[]; muted: boolean; touch: boolean; pad: VirtualPad;
  mapRef(c: HTMLCanvasElement | null): void; onPause(): void; onMute(): void;
}

const ITEM_ICON = { turbo: Zap, cascara: Banana, escudo: Shield };
const ORDER: ItemId[] = ['turbo', 'cascara', 'escudo'];

function ItemSlot({ item, rolling }: { item: ItemId | null; rolling: boolean }) {
  const [spin, setSpin] = useState(0);
  useEffect(() => { if (!rolling) return; const t = window.setInterval(() => setSpin(s => s + 1), 70); return () => window.clearInterval(t); }, [rolling]);
  const shown = rolling ? ORDER[spin % 3] : item, Icon = shown ? ITEM_ICON[shown] : null;
  return (
    <div className={clsx('kr-panel grid h-[76px] w-[76px] place-items-center sm:h-[88px] sm:w-[88px]', !rolling && item && 'kr-pop')}
      style={{ background: shown ? `radial-gradient(circle at 50% 40%, #fff, ${ITEM_INFO[shown].color})` : 'rgba(255,255,255,0.75)' }}>
      {Icon ? <Icon size={42} strokeWidth={2.6} color="#141a33" /> : <span className="text-3xl font-black text-[#141a33]/25">?</span>}
    </div>
  );
}

function Speedo({ kmh, n, boost }: { kmh: number; n: number; boost: boolean }) {
  const R = 54, L = Math.PI * R * 1.5, dash = L * Math.min(1, n);
  return (
    <div className="relative h-[130px] w-[150px]">
      <svg viewBox="0 0 150 130" className="absolute inset-0 h-full w-full">
        <circle cx="75" cy="72" r={R} fill="rgba(20,26,51,0.78)" stroke="#fff" strokeWidth="3" />
        <circle cx="75" cy="72" r={R - 8} fill="none" stroke="rgba(255,255,255,0.18)" strokeWidth="9"
          strokeDasharray={`${L * (R - 8) / R} 999`} transform="rotate(135 75 72)" strokeLinecap="round" />
        <circle cx="75" cy="72" r={R - 8} fill="none" stroke={boost ? '#ff7a1a' : n > 0.8 ? '#ffd23f' : '#3dff9a'} strokeWidth="9"
          strokeDasharray={`${dash * (R - 8) / R} 999`} transform="rotate(135 75 72)" strokeLinecap="round" />
      </svg>
      <div className="absolute inset-x-0 top-[44px] text-center"><div className="kr-num text-4xl leading-none">{kmh}</div><div className="text-[10px] font-black tracking-widest text-white/80">KM/H</div></div>
      {boost && <Flame className="kr-blink absolute bottom-1 left-1/2 -translate-x-1/2 text-[#ff7a1a]" size={22} />}
    </div>
  );
}

function TouchBtn({ k, pad, className, children }: { k: keyof VirtualPad; pad: VirtualPad; className?: string; children: React.ReactNode }) {
  const set = (v: boolean) => (e: React.PointerEvent) => { e.preventDefault(); pad[k] = v; };
  return (
    <button onPointerDown={set(true)} onPointerUp={set(false)} onPointerLeave={set(false)} onPointerCancel={set(false)}
      className={clsx('kr-btn pointer-events-auto grid place-items-center bg-white/85 active:bg-[#ffd23f]', className)}>{children}</button>
  );
}

export default function Hud({ hud, toasts, muted, touch, pad, mapRef, onPause, onMute }: Props) {
  const posColor = hud.pos === 1 ? '#ffd23f' : hud.pos === 2 ? '#e5e7eb' : hud.pos === 3 ? '#f59e0b' : '#ffffff';
  return (
    <div className="pointer-events-none absolute inset-0">
      {/* Posición y vuelta */}
      <div className="absolute left-3 top-3 flex items-end gap-3 sm:left-5 sm:top-4">
        <div className="kr-num leading-none" style={{ color: posColor }}>
          <span className="text-7xl sm:text-8xl">{hud.pos}</span><span className="text-3xl">º</span>
          <span className="ml-1 text-2xl text-white/90">/{hud.total}</span>
        </div>
        <div className="kr-dark mb-2 px-3 py-1.5"><div className="text-[10px] font-black uppercase tracking-widest text-[#ffd23f]">Vuelta</div>
          <div className="text-2xl font-black italic leading-none">{hud.lap}<span className="text-base opacity-70">/{hud.laps}</span></div></div>
      </div>

      {/* Tiempos */}
      <div className="kr-dark absolute left-1/2 top-3 -translate-x-1/2 px-4 py-1.5 text-center sm:top-4">
        <div className="font-mono text-xl font-black tabular-nums sm:text-2xl">{formatTime(hud.time)}</div>
        <div className="flex gap-3 text-[10px] font-bold uppercase tracking-wider text-white/75">
          <span>Vuelta {formatTime(hud.lapTime)}</span><span className="text-[#3dff9a]">Mejor {formatTime(hud.bestLap)}</span>
        </div>
      </div>

      {/* Objeto + botones */}
      <div className="absolute right-3 top-3 flex items-start gap-2 sm:right-5 sm:top-4">
        <ItemSlot item={hud.item} rolling={hud.rolling} />
        <div className="flex flex-col gap-2">
          <button onClick={onPause} aria-label="Pausa" className="kr-btn pointer-events-auto grid h-10 w-10 place-items-center bg-white"><Pause size={18} /></button>
          <button onClick={onMute} aria-label="Sonido" className="kr-btn pointer-events-auto grid h-10 w-10 place-items-center bg-white">{muted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
        </div>
      </div>

      {/* Minimapa */}
      <div className={clsx('kr-dark absolute overflow-hidden p-1', touch ? 'left-3 top-28 h-[110px] w-[130px]' : 'bottom-4 left-4 h-[170px] w-[200px]')}>
        <canvas ref={mapRef} className="h-full w-full" />
      </div>

      {/* Velocímetro + estados */}
      <div className={clsx('absolute flex flex-col items-end gap-1', touch ? 'right-3 top-32 scale-75 origin-top-right' : 'bottom-3 right-4')}>
        <div className="flex gap-1.5">
          {hud.shield > 0 && <span className="kr-dark flex items-center gap-1 px-2 py-0.5 text-xs font-black text-[#5ad8ff]"><Shield size={13} /> {Math.ceil(hud.shield)}s</span>}
          {hud.drift > 0 && <span className="kr-dark px-2 py-0.5 text-xs font-black" style={{ color: hud.drift >= 2 ? '#ffa31a' : hud.drift >= 1 ? '#5ad8ff' : '#fff' }}>DERRAPE {hud.drift >= 2 ? '★★' : hud.drift >= 1 ? '★' : '·'}</span>}
        </div>
        <Speedo kmh={hud.kmh} n={hud.speedN} boost={hud.boost > 0} />
      </div>

      {/* Cuenta atrás, avisos */}
      {hud.countdown && <div key={hud.countdown} className="kr-pop absolute inset-x-0 top-[26%] text-center">
        <span className={clsx('kr-title text-[120px] sm:text-[170px]', hud.countdown === '¡YA!' && 'kr-red')}>{hud.countdown}</span></div>}
      {hud.wrong && <div className="kr-blink absolute inset-x-0 top-[38%] text-center">
        <span className="rounded-2xl border-4 border-white bg-[#ff2d3d] px-6 py-2 text-3xl font-black italic text-white">¡SENTIDO CONTRARIO!</span></div>}
      <div className="absolute inset-x-0 top-[22%] flex flex-col items-center gap-2">
        {toasts.map(t => <div key={t.id} className="kr-toast kr-num text-4xl sm:text-5xl" style={{ color: t.color }}>{t.text}</div>)}
      </div>

      {/* Controles táctiles */}
      {touch && (
        <>
          <div className="absolute bottom-5 left-4 flex gap-3">
            <TouchBtn k="left" pad={pad} className="h-20 w-20"><ChevronLeft size={40} /></TouchBtn>
            <TouchBtn k="right" pad={pad} className="h-20 w-20"><ChevronRight size={40} /></TouchBtn>
          </div>
          <div className="absolute bottom-5 right-4 grid grid-cols-2 gap-3">
            <TouchBtn k="item" pad={pad} className="h-16 w-16 bg-[#ffd23f]/90"><Zap size={26} /></TouchBtn>
            <TouchBtn k="drift" pad={pad} className="h-16 w-16 text-xs font-black">DERR.</TouchBtn>
            <TouchBtn k="down" pad={pad} className="h-16 w-16"><ArrowDown size={28} /></TouchBtn>
            <TouchBtn k="up" pad={pad} className="h-16 w-16 bg-[#3dff9a]/90"><ArrowUp size={30} /></TouchBtn>
          </div>
        </>
      )}
    </div>
  );
}

import { Flag, Medal, Play, Snowflake, Sun, Sunset, Trophy, Volume2, VolumeX } from 'lucide-react';
import clsx from 'clsx';
import { DiffId, DIFFS, formatTime, RACERS, SaveData, THEMES, TrackId } from '../game/config';

interface Props {
  save: SaveData; muted: boolean;
  onTrack(id: TrackId): void; onDiff(id: DiffId): void; onPlay(): void; onMute(): void;
}

const ICONS = { Sun, Sunset, Snowflake };

export default function Menu({ save, muted, onTrack, onDiff, onPlay, onMute }: Props) {
  return (
    <div className="absolute inset-0 overflow-y-auto">
      <div className="absolute inset-0 bg-gradient-to-r from-[#141a33]/55 via-[#141a33]/15 to-transparent pointer-events-none" />
      <button onClick={onMute} aria-label="Sonido" className="kr-btn absolute right-4 top-4 z-10 grid h-12 w-12 place-items-center bg-white">
        {muted ? <VolumeX size={22} /> : <Volume2 size={22} />}
      </button>

      <div className="relative flex min-h-full flex-col justify-center gap-5 p-5 sm:p-8 md:max-w-[620px]">
        <div className="kr-float">
          <div className="kr-checker mb-3 h-3 w-40 rounded-sm border-2 border-[#141a33]" />
          <h1 className="kr-title text-6xl sm:text-8xl">KART<br /><span className="kr-red">RALLY</span></h1>
          <p className="mt-4 max-w-md text-base font-bold text-white drop-shadow-[0_2px_0_rgba(20,26,51,0.9)] sm:text-lg">
            Tres vueltas, cinco rivales y un montón de cajas sorpresa. Derrapa, lanza cáscaras y cruza la meta el primero.
          </p>
        </div>

        <div className="kr-panel p-4">
          <div className="mb-2 flex items-center gap-2 text-xs font-black uppercase tracking-widest text-[#141a33]/70"><Flag size={14} /> Circuito</div>
          <div className="grid grid-cols-3 gap-2">
            {THEMES.map(t => {
              const Icon = ICONS[t.icon];
              const sel = save.track === t.id;
              return (
                <button key={t.id} onClick={() => onTrack(t.id)}
                  className={clsx('kr-btn flex flex-col items-start gap-1 p-2.5 text-left not-italic', sel ? 'bg-[#ffd23f]' : 'bg-white')}>
                  <span className="grid h-8 w-8 place-items-center rounded-lg border-2 border-[#141a33]" style={{ background: `linear-gradient(160deg, ${t.skyTop}, ${t.skyBottom} 60%, ${t.ground} 61%)` }}>
                    <Icon size={16} className="text-white drop-shadow" />
                  </span>
                  <span className="text-sm font-black leading-tight">{t.name}</span>
                  <span className="hidden text-[11px] font-semibold not-italic leading-tight text-[#141a33]/70 sm:block">{t.desc}</span>
                  <span className="mt-auto flex items-center gap-1 text-[11px] font-bold not-italic text-[#141a33]/80">
                    <Trophy size={11} /> {formatTime(save.best[t.id] ?? 0)}
                    {save.bestPos[t.id] ? <span className="ml-1 rounded bg-[#141a33] px-1 text-white">{save.bestPos[t.id]}º</span> : null}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="mb-2 mt-4 text-xs font-black uppercase tracking-widest text-[#141a33]/70">Dificultad</div>
          <div className="grid grid-cols-3 gap-2">
            {DIFFS.map(d => <button key={d.id} onClick={() => onDiff(d.id)} className={clsx('kr-btn px-2 py-2 text-sm', save.diff === d.id ? 'bg-[#ff2d3d] text-white' : 'bg-white')}>
              {d.name}<span className="block text-[10px] font-semibold not-italic opacity-80">{d.desc}</span></button>)}
          </div>

          <button onClick={onPlay}
            className="kr-btn mt-5 flex w-full items-center justify-center gap-3 bg-gradient-to-b from-[#ffe46b] to-[#ffb21a] py-4 text-3xl text-[#141a33]">
            <Play size={30} fill="#141a33" /> Jugar
          </button>
        </div>

        <div className="flex flex-wrap items-stretch gap-3">
          <div className="kr-dark flex-1 px-4 py-3 text-xs leading-relaxed sm:text-sm">
            <div className="mb-1 font-black uppercase tracking-wider text-[#ffd23f]">Controles</div>
            <b>↑ / W</b> acelerar · <b>↓ / S</b> frenar · <b>← → / A D</b> girar<br />
            <b>Shift / X</b> derrapar (suelta para mini-turbo) · <b>Espacio</b> usar objeto · <b>Esc / P</b> pausa
          </div>
          <div className="kr-dark flex items-center gap-3 px-4 py-3">
            <Medal size={26} className="text-[#ffd23f]" />
            <div><div className="text-2xl font-black italic leading-none">{save.wins}</div><div className="text-[11px] font-bold uppercase opacity-80">victorias</div></div>
          </div>
        </div>

        <div className="flex flex-wrap gap-1.5">{RACERS.slice(1).map(r => <span key={r.name} className="rounded-full border-2 border-[#141a33] bg-white py-0.5 pl-3 pr-2.5 text-[11px] font-black italic" style={{ boxShadow: `inset 6px 0 0 ${r.color}` }}>{r.name}</span>)}</div>
      </div>
    </div>
  );
}

import { Home, Medal, Play, RotateCcw, Timer, Trophy } from 'lucide-react';
import clsx from 'clsx';
import { formatTime } from '../game/config';
import { RaceResult } from '../game/engine';

interface PauseProps { onResume(): void; onRestart(): void; onMenu(): void }

export function PauseMenu({ onResume, onRestart, onMenu }: PauseProps) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-[#141a33]/55 p-4">
      <div className="kr-panel kr-pop w-full max-w-xs p-6 text-center">
        <div className="kr-checker mx-auto mb-3 h-3 w-24 rounded-sm border-2 border-[#141a33]" />
        <h2 className="kr-title mb-5 text-5xl">PAUSA</h2>
        <div className="flex flex-col gap-3">
          <button onClick={onResume} className="kr-btn flex items-center justify-center gap-2 bg-[#ffd23f] py-3 text-xl"><Play size={20} fill="#141a33" /> Continuar</button>
          <button onClick={onRestart} className="kr-btn flex items-center justify-center gap-2 bg-white py-3 text-lg"><RotateCcw size={18} /> Reiniciar carrera</button>
          <button onClick={onMenu} className="kr-btn flex items-center justify-center gap-2 bg-white py-3 text-lg"><Home size={18} /> Menú principal</button>
        </div>
      </div>
    </div>
  );
}

interface ResultProps { r: RaceResult; record: boolean; trackName: string; best: number; onRetry(): void; onMenu(): void }

export function Results({ r, record, trackName, best, onRetry, onMenu }: ResultProps) {
  const title = r.pos === 1 ? '¡VICTORIA!' : r.pos <= 3 ? '¡AL PODIO!' : '¡CARRERA TERMINADA!';
  return (
    <div className="absolute inset-0 overflow-y-auto bg-[#141a33]/50 p-4">
      <div className="flex min-h-full items-center justify-center">
        <div className="kr-panel kr-pop w-full max-w-md p-5 sm:p-6">
          <div className="flex items-center justify-between">
            <div className="text-xs font-black uppercase tracking-widest text-[#141a33]/60">{trackName}</div>
            {record && <span className="kr-blink rounded-full bg-[#ff2d3d] px-3 py-1 text-xs font-black text-white">¡NUEVO RÉCORD!</span>}
          </div>
          <div className="mt-2 flex items-center gap-4">
            <div className="kr-num text-8xl leading-none" style={{ color: r.pos === 1 ? '#ffd23f' : r.pos <= 3 ? '#f59e0b' : '#fff' }}>{r.pos}º</div>
            <h2 className="kr-title text-3xl sm:text-4xl">{title}</h2>
          </div>
          <div className="mt-4 grid grid-cols-3 gap-2 text-center">
            {[
              { icon: Timer, label: 'Tiempo', v: formatTime(r.time) },
              { icon: Medal, label: 'Mejor vuelta', v: formatTime(r.bestLap) },
              { icon: Trophy, label: 'Récord', v: formatTime(best) },
            ].map(s => (
              <div key={s.label} className="rounded-xl border-2 border-[#141a33] bg-[#fff6d6] px-1 py-2">
                <s.icon size={16} className="mx-auto" />
                <div className="text-[10px] font-black uppercase tracking-wider text-[#141a33]/60">{s.label}</div>
                <div className="font-mono text-sm font-black tabular-nums sm:text-base">{s.v}</div>
              </div>
            ))}
          </div>
          <ol className="mt-4 overflow-hidden rounded-xl border-2 border-[#141a33]">
            {r.standings.map((s, i) => (
              <li key={s.name} className={clsx('flex items-center gap-3 px-3 py-1.5 text-sm font-bold', s.player ? 'bg-[#ffd23f]' : i % 2 ? 'bg-white' : 'bg-[#f3f4f8]')}>
                <span className="w-6 font-black italic">{i + 1}º</span>
                <span className="h-3 w-3 rounded-full border-2 border-[#141a33]" style={{ background: s.color }} />
                <span className="flex-1 italic">{s.name}</span>
                <span className="font-mono tabular-nums">{s.time !== null ? formatTime(s.time) : 'en pista'}</span>
              </li>
            ))}
          </ol>
          <div className="mt-5 grid grid-cols-2 gap-3">
            <button onClick={onRetry} className="kr-btn flex items-center justify-center gap-2 bg-[#ffd23f] py-3 text-lg"><RotateCcw size={18} /> Reintentar</button>
            <button onClick={onMenu} className="kr-btn flex items-center justify-center gap-2 bg-white py-3 text-lg"><Home size={18} /> Menú</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// Pilotos IA: siguen la trazada con un carril propio, frenan en curvas, esquivan cáscaras y usan objetos.
import { DiffDef } from './config';
import { Items } from './items';
import { Controls, Kart, MAX_V } from './karts';
import { Track } from './track';

export interface AiContext { diff: DiffDef; leaderGap: (k: Kart) => number; behindGap: (k: Kart) => number; finalLap: boolean }

export function aiDrive(k: Kart, dt: number, track: Track, items: Items, ctx: AiContext): Controls & { use: boolean } {
  const spacing = track.length / track.N;
  k.laneT -= dt;
  if (k.laneT <= 0) { k.lane = (Math.random() - 0.5) * 9; k.laneT = 2 + Math.random() * 3.5; }
  const peel = items.peelAhead(k, track);
  let lane = k.lane;
  if (peel !== null && Math.abs(peel - lane) < 3) lane = peel + (peel > 0 ? -4.2 : 4.2);

  // Curvatura de lo que viene
  let curv = 0;
  for (let o = 0; o <= 40; o += 10) curv = Math.max(curv, track.curv[track.wrap(k.idx + o + Math.round(k.speed * 0.6))]);
  // Si la curva es cerrada, toma el interior
  const inner = track.curv[track.wrap(k.idx + 30)] > 0.55 ? Math.sign(cross(track, k.idx)) * 3.5 : 0;
  const look = Math.round((8 + k.speed * 0.42) / spacing);
  const ti = track.wrap(k.idx + look);
  const tl = Math.max(-5.5, Math.min(5.5, inner || lane));
  const tx = track.px[ti] + track.rx(ti) * tl, tz = track.pz[ti] + track.rz(ti) * tl;
  const desired = Math.atan2(tx - k.x, tz - k.z);
  let d = desired - k.heading; d = Math.atan2(Math.sin(d), Math.cos(d));
  const steer = Math.max(-1, Math.min(1, -d * 2.4));

  const gap = ctx.leaderGap(k); // >0: el jugador va por delante
  const rub = Math.max(-0.1, Math.min(0.12, gap / 260)) * ctx.diff.rubber;
  k.skill = ctx.diff.ai * (1 + rub) * (ctx.finalLap ? 1.03 : 1) * (0.97 + (k.id % 3) * 0.02);
  const target = MAX_V * k.skill * (1 - Math.min(0.34, curv * 0.4));
  const throttle = k.speed < target ? 1 : 0;
  const brake = k.speed > target + 5 ? 1 : 0;

  // Objetos
  let use = false;
  k.itemT -= dt;
  if (k.item && k.rollT <= 0 && k.itemT <= 0) {
    k.itemT = (0.6 + Math.random() * 2.5) / Math.max(0.2, ctx.diff.itemRate);
    if (Math.random() < ctx.diff.itemRate) {
      if (k.item === 'turbo') use = curv < 0.4;
      else if (k.item === 'cascara') use = ctx.behindGap(k) < 22 || Math.random() < 0.15;
      else use = true;
    }
  }
  return { throttle, brake, steer, drift: false, use };
}

/** Signo de giro de la curva que viene (positivo = hacia la derecha, lat +). */
function cross(track: Track, i: number) {
  const a = track.wrap(i), b = track.wrap(i + 40);
  return track.tx[a] * track.tz[b] - track.tz[a] * track.tx[b];
}

// Audio procedural con Web Audio API: motor, efectos y una musiquilla alegre en bucle.
class Sound {
  private ctx: AudioContext | null = null; private master: GainNode | null = null; private musicGain: GainNode | null = null;
  private engOsc: OscillatorNode | null = null; private engOsc2: OscillatorNode | null = null;
  private engGain: GainNode | null = null; private engFilter: BiquadFilterNode | null = null;
  private musicTimer = 0; private step = 0; private nextT = 0;
  muted = false;

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.55; this.master.connect(this.ctx.destination);
      this.engGain = this.ctx.createGain(); this.engGain.gain.value = 0;
      this.engFilter = this.ctx.createBiquadFilter(); this.engFilter.type = 'lowpass'; this.engFilter.frequency.value = 700;
      this.engOsc = this.ctx.createOscillator(); this.engOsc.type = 'sawtooth';
      this.engOsc2 = this.ctx.createOscillator(); this.engOsc2.type = 'square';
      this.engOsc.connect(this.engFilter); this.engOsc2.connect(this.engFilter);
      this.engFilter.connect(this.engGain); this.engGain.connect(this.master);
      this.engOsc.start(); this.engOsc2.start();
      this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = 0.16; this.musicGain.connect(this.master);
    } catch { this.ctx = null; }
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.03);
  }

  /** Sonido del motor del jugador (0 = parado). */
  engine(speedN: number, on: boolean, boost: boolean) {
    if (!this.ctx || !this.engOsc || !this.engOsc2 || !this.engGain || !this.engFilter) return;
    const t = this.ctx.currentTime, f = 55 + speedN * 120 + (boost ? 40 : 0);
    this.engOsc.frequency.setTargetAtTime(f, t, 0.05);
    this.engOsc2.frequency.setTargetAtTime(f * 0.502, t, 0.05);
    this.engFilter.frequency.setTargetAtTime(500 + speedN * 1400, t, 0.08);
    this.engGain.gain.setTargetAtTime(on ? 0.05 + speedN * 0.05 : 0, t, 0.1);
  }

  private tone(freq: number, dur: number, type: OscillatorType = 'square', vol = 0.2, slide = 0, delay = 0, dest?: AudioNode) {
    if (!this.ctx || !this.master) return;
    const t = this.ctx.currentTime + delay, o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(dest ?? this.master); o.start(t); o.stop(t + dur + 0.02);
  }

  private noise(dur: number, vol: number, freq: number, q = 1, sweep = 0) {
    if (!this.ctx || !this.master) return;
    const len = Math.floor(this.ctx.sampleRate * dur), buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    const s = this.ctx.createBufferSource(), f = this.ctx.createBiquadFilter(), g = this.ctx.createGain(), t = this.ctx.currentTime;
    s.buffer = buf; f.type = 'bandpass'; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(60, freq + sweep), t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(); s.stop(t + dur);
  }

  click() { this.tone(660, 0.06, 'square', 0.08); }
  beep(go: boolean) { this.tone(go ? 880 : 440, go ? 0.5 : 0.22, 'square', 0.16); }
  pickup() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.09, 'triangle', 0.14, 0, i * 0.05)); }
  item() { this.tone(300, 0.15, 'sawtooth', 0.1, 400); }
  boost() { this.noise(0.6, 0.35, 600, 0.8, 2400); this.tone(220, 0.4, 'sawtooth', 0.08, 300); }
  miniTurbo(l: number) { this.tone(l === 2 ? 700 : 520, 0.18, 'square', 0.1, 500); this.noise(0.3, 0.2, 1200, 1, 1500); }
  spin() { this.tone(700, 0.6, 'square', 0.12, -560); this.noise(0.4, 0.2, 400, 0.7); }
  shield() { [392, 523, 784].forEach((f, i) => this.tone(f, 0.25, 'sine', 0.14, 0, i * 0.06)); }
  block() { this.tone(1200, 0.25, 'triangle', 0.14, -600); }
  wall(v: number) { this.noise(0.25, Math.min(0.5, 0.1 + v * 0.02), 180, 0.9); }
  lap() { [659, 784, 988].forEach((f, i) => this.tone(f, 0.16, 'square', 0.12, 0, i * 0.09)); }
  finish(win: boolean) {
    const notes = win ? [523, 659, 784, 1046, 784, 1046] : [392, 440, 523, 659];
    notes.forEach((f, i) => this.tone(f, 0.24, 'square', 0.13, 0, i * 0.14));
  }

  startMusic() {
    if (!this.ctx || this.musicTimer) return;
    this.nextT = this.ctx.currentTime + 0.1; this.step = 0;
    const bass = [130.8, 130.8, 174.6, 174.6, 196, 196, 146.8, 164.8];
    const mel = [523, 0, 659, 784, 698, 0, 659, 523, 587, 0, 698, 880, 784, 659, 587, 0];
    this.musicTimer = window.setInterval(() => {
      if (!this.ctx || !this.musicGain) return;
      while (this.nextT < this.ctx.currentTime + 0.25) {
        const d = this.nextT - this.ctx.currentTime, s = this.step;
        if (s % 2 === 0) this.tone(bass[(s >> 2) % 8], 0.2, 'triangle', 0.5, 0, Math.max(0, d), this.musicGain);
        const m = mel[s % 16];
        if (m) this.tone(m, 0.12, 'square', 0.16, 0, Math.max(0, d), this.musicGain);
        this.nextT += 0.15; this.step++;
      }
    }, 90);
  }
  stopMusic() { if (this.musicTimer) { window.clearInterval(this.musicTimer); this.musicTimer = 0; } }


}

export const sound = new Sound();

