export function formatTime(sec: number) {
  if (!isFinite(sec) || sec <= 0) return '--:--.--';
  const m = Math.floor(sec / 60), s = Math.floor(sec % 60), c = Math.floor((sec * 100) % 100);
  return `${m}:${String(s).padStart(2, '0')}.${String(c).padStart(2, '0')}`;
}

// Motor de la carrera: escena, bucle, cuenta atrás, control del jugador, IA, objetos, colisiones, cámara y HUD.
import * as THREE from 'three';
import { aiDrive } from './ai';
import { sound } from './audio';
import { DiffDef, DIFFS, ItemId, ITEM_INFO, RACERS, Theme, THEMES, TOTAL_LAPS } from './config';
import { C, Fx } from './fx';
import { Input } from './input';
import { Items } from './items';
import { Controls, Kart, KartEvents, MAX_V } from './karts';
import { Minimap } from './minimap';
import { Scenery } from './scenery';
import { canvasTexture, LIGHT_K, lin, radialTexture, setupRenderer } from './three-compat';
import { Track } from './track';

export type Mode = 'attract' | 'countdown' | 'race' | 'finish';

export interface HudState {
  pos: number; total: number; lap: number; laps: number; time: number; lapTime: number; bestLap: number;
  kmh: number; speedN: number; item: ItemId | null; rolling: boolean; boost: number; shield: number;
  drift: number; countdown: string | null; wrong: boolean; mode: Mode;
}
export interface Standing { name: string; color: string; time: number | null; player: boolean }
export interface RaceResult { pos: number; time: number; bestLap: number; standings: Standing[] }
export interface GameCallbacks { onHud(h: HudState): void; onEvent(text: string, color: string): void; onFinish(r: RaceResult): void }

const ITEMS: ItemId[] = ['turbo', 'cascara', 'escudo'];

export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer; private scene = new THREE.Scene(); private camera = new THREE.PerspectiveCamera(64, 1, 0.5, 3000);
  private sun: THREE.DirectionalLight; private hemi: THREE.HemisphereLight; private fx = new Fx();
  private track!: Track; private scenery!: Scenery; private items!: Items;
  private theme: Theme = THEMES[0]; private diff: DiffDef = DIFFS[1];
  private karts: Kart[] = []; private order: Kart[] = []; private tags: THREE.Sprite[] = [];
  private shadowTex = radialTexture([[0, 'rgba(0,0,0,0.55)'], [1, 'rgba(0,0,0,0)']]);
  private flameTex = radialTexture([[0, 'rgba(255,255,230,1)'], [0.35, 'rgba(255,170,60,0.8)'], [1, 'rgba(255,60,0,0)']]);
  private shadowMat = new THREE.MeshBasicMaterial({ map: this.shadowTex, transparent: true, depthWrite: false });
  private shadowGeo = new THREE.PlaneGeometry(2.6, 3.6);
  private minimap: Minimap | null = null; private clock = new THREE.Clock(); private raf = 0; private ro: ResizeObserver;
  private mode: Mode = 'attract'; private paused = false;
  private time = 0; private raceT = 0; private cdT = 0; private cdShown = ''; private finishT = 0;
  private shake = 0; private hudClock = 0; private mapTick = 0; private finalLap = false; private wrongShown = false;
  private snap = true; private camPos = new THREE.Vector3(); private camLook = new THREE.Vector3();
  private kartEv: KartEvents;

  constructor(private host: HTMLElement, private cb: GameCallbacks) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.domElement.style.display = 'block'; host.appendChild(this.renderer.domElement);
    this.hemi = new THREE.HemisphereLight('#ffffff', '#ffffff', 0.8 * LIGHT_K);
    this.sun = new THREE.DirectionalLight('#ffffff', 1.2 * LIGHT_K);
    this.scene.add(this.hemi, this.sun, this.fx.group);

    RACERS.forEach((r, i) => {
      const k = new Kart(r, i, i === 0, this.flameTex);
      const sh = new THREE.Mesh(this.shadowGeo, this.shadowMat);
      sh.rotation.x = -Math.PI / 2; sh.position.y = 0.06; k.mesh.add(sh);
      this.karts.push(k); this.scene.add(k.mesh);
      const tag = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.nameTex(r.name, r.color), depthWrite: false, transparent: true }));
      tag.scale.set(3.6, 0.9, 1); tag.position.y = 3.1; tag.visible = i !== 0;
      k.mesh.add(tag); this.tags.push(tag);
    });
    this.kartEv = {
      wall: (k, v) => { this.fx.sparks(k.x, 0.7, k.z, C.spark, 10, 5); k.bump = 0.6; if (k.isPlayer && this.mode !== 'attract') { sound.wall(v); this.shake = Math.min(0.6, this.shake + v * 0.02); } },
      miniTurbo: (k, l) => { if (k.isPlayer && this.mode === 'race') { sound.miniTurbo(l); this.cb.onEvent(l === 2 ? '¡SUPER MINI-TURBO!' : '¡MINI-TURBO!', l === 2 ? '#ffa31a' : '#5ad8ff'); } },
    };
    this.loadTrack(THEMES[0]);
    this.toAttract(THEMES[0]);
    this.ro = new ResizeObserver(() => this.resize()); this.ro.observe(host);
    this.resize(); this.loop();
  }

  private nameTex(name: string, color: string) {
    return canvasTexture(256, 64, g => {
      g.fillStyle = 'rgba(15,18,30,0.72)'; g.beginPath();
      const w = 236; g.moveTo(10 + 14, 8); g.arcTo(10 + w, 8, 10 + w, 56, 14); g.arcTo(10 + w, 56, 10, 56, 14); g.arcTo(10, 56, 10, 8, 14); g.arcTo(10, 8, 10 + w, 8, 14); g.fill();
      g.fillStyle = color; g.fillRect(22, 20, 8, 24);
      g.fillStyle = '#fff'; g.font = 'italic 800 30px Arial'; g.textBaseline = 'middle'; g.fillText(name, 40, 33);
    });
  }

  attachMinimap(c: HTMLCanvasElement | null) {
    this.minimap = c ? new Minimap(c) : null;
    if (this.minimap && this.track) this.minimap.setTrack(this.track);
  }

  private loadTrack(theme: Theme) {
    if (this.track && this.theme === theme) return;
    if (this.track) { this.scene.remove(this.track.group, this.scenery.group, this.items.group); this.track.dispose(); this.scenery.dispose(); this.items.dispose(); }
    this.theme = theme; this.track = new Track(theme); this.scenery = new Scenery(this.track, theme); this.items = new Items(this.track);
    this.scene.add(this.track.group, this.scenery.group, this.items.group);
    this.scene.fog = new THREE.Fog(lin(theme.fog), 150, 950); this.scene.background = new THREE.Color(theme.fog);
    this.hemi.color.copy(lin(theme.hemiSky)); this.hemi.groundColor.copy(lin(theme.hemiGround));
    this.sun.color.copy(lin(theme.light)); this.sun.intensity = theme.lightI * LIGHT_K;
    this.sun.position.copy(this.scenery.sunDir).multiplyScalar(100);
    this.minimap?.setTrack(this.track);
  }

  private grid() {
    this.items.reset(); this.fx.clear();
    // Parrilla: el jugador sale último (6º)
    this.karts.forEach((k, i) => {
      const slot = i === 0 ? 5 : i - 1;
      k.place(this.track, -6 - Math.floor(slot / 2) * 6 - (slot % 2) * 2.5, slot % 2 ? 3.4 : -3.4);
      k.lane = slot % 2 ? 3 : -3; k.laneT = 1 + Math.random() * 2; k.itemT = 2 + Math.random() * 3;
    });
    this.order = [...this.karts];
    this.raceT = 0; this.finalLap = false; this.shake = 0;
  }

  newRace(theme: Theme, diff: DiffDef) {
    this.loadTrack(theme); this.diff = diff; this.grid(); this.input.reset();
    this.mode = 'countdown'; this.cdT = 3.6; this.cdShown = ''; this.paused = false; this.tags.forEach((t, i) => { t.visible = i > 0; });
    const p = this.karts[0];
    this.camPos.set(p.x + Math.sin(p.heading) * 30, 14, p.z + Math.cos(p.heading) * 30);
    sound.startMusic();
  }

  toAttract(theme: Theme) {
    this.loadTrack(theme); this.diff = DIFFS[1]; this.grid();
    this.karts.forEach(k => { k.lap = 1; k.half = false; });
    this.mode = 'attract'; this.paused = false; this.snap = true; this.tags.forEach(t => { t.visible = false; });
    sound.engine(0, false, false); sound.stopMusic();
  }

  setPaused(p: boolean) { this.paused = p; if (p) sound.engine(0, false, false); this.clock.getDelta(); }

  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight); this.renderer.setSize(w, h, false);
    this.renderer.domElement.style.width = '100%'; this.renderer.domElement.style.height = '100%';
    this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
  }

  private loop = () => {
    this.raf = requestAnimationFrame(this.loop);
    const raw = this.clock.getDelta();
    if (!this.paused) this.step(Math.min(0.05, raw), Math.min(0.5, raw));
    this.renderer.render(this.scene, this.camera);
  };

  private useItem(k: Kart) {
    const it = k.item; if (!it || k.rollT > 0) return; k.item = null;
    if (it === 'turbo') { k.boostT = Math.max(k.boostT, 1.7); if (k.isPlayer) { sound.boost(); this.shake = 0.25; } }
    else if (it === 'cascara') { this.items.dropPeel(k); if (k.isPlayer) sound.item(); }
    else { k.shieldT = 8; if (k.isPlayer) sound.shield(); }
    if (k.isPlayer) this.cb.onEvent(ITEM_INFO[it].name.toUpperCase() + '!', ITEM_INFO[it].color);
  }

  private step(dt: number, realDt: number) {
    this.time += dt;
    const player = this.karts[0], racing = this.mode === 'race' || this.mode === 'finish';

    if (this.mode === 'countdown') {
      this.cdT -= realDt;
      const label = this.cdT > 2.6 ? '3' : this.cdT > 1.6 ? '2' : this.cdT > 0.6 ? '1' : '¡YA!';
      if (label !== this.cdShown) { this.cdShown = label; sound.beep(label === '¡YA!'); }
      if (this.cdT <= 0.6) { this.mode = 'race'; }
    }
    if (this.mode === 'race' || this.mode === 'finish') this.raceT += dt;
    const live = this.mode !== 'countdown';

    const leaderGap = (k: Kart) => (this.mode === 'attract' ? 0 : player.progress - k.progress);
    const behindGap = (k: Kart) => this.karts.reduce((g, o) => (o !== k && o.progress < k.progress ? Math.min(g, k.progress - o.progress) : g), Infinity);
    const ctx = { diff: this.diff, leaderGap, behindGap, finalLap: this.finalLap };

    for (const k of this.karts) {
      let c: Controls = { throttle: 0, brake: 0, steer: 0, drift: false };
      if (live) {
        if (k.isPlayer && this.mode === 'race') {
          c = { throttle: this.input.up ? 1 : 0, brake: this.input.down ? 1 : 0, steer: this.input.steer, drift: this.input.drift };
          if (this.input.itemPressed()) this.useItem(k);
        } else {
          const a = aiDrive(k, dt, this.track, this.items, ctx);
          c = a; if (a.use) this.useItem(k);
        }
      }
      if (k.rollT > 0) { k.rollT -= dt; if (k.rollT <= 0 && k.isPlayer && this.mode === 'race') sound.pickup(); }
      const crossed = k.step(dt, c, this.track, this.kartEv, this.mode === 'attract' ? 0.92 : 1);
      if (crossed && racing) this.onLap(k);
      k.sync(dt, this.time);
      // Partículas por kart
      const hx = Math.sin(k.heading), hz = Math.cos(k.heading);
      if (k.offroad && k.speed > 6 && Math.random() < 0.6) this.fx.dust(k.x - hx * 1.5, k.z - hz * 1.5, this.theme.flora === 'pine' ? C.snow : this.theme.flora === 'cactus' ? C.dust : C.grass);
      if (k.boostT > 0) this.fx.flame(k.x, k.z, hx, hz);
      if (k.driftDir !== 0) {
        const col = k.driftT > 1.7 ? C.orange : k.driftT > 0.8 ? C.blue : C.smoke;
        for (const s of [-1, 1]) this.fx.drift(k.x - hx * 1.3 + hz * s * 1.1, k.z - hz * 1.3 - hx * s * 1.1, col);
      }
      if (k.spinT > 0 && Math.random() < 0.5) this.fx.dust(k.x, k.z, C.smoke);
    }
    this.collide();
    this.items.update(dt, this.time, this.karts, {
      pickup: (k, x, z) => {
        this.fx.burst(x, 1.3, z);
        if (k.item || k.rollT > 0) return;
        const pos = this.order.indexOf(k) + 1;
        k.item = this.mode === 'attract' ? ITEMS[Math.floor(Math.random() * 3)] : Items.roll(pos, this.karts.length);
        k.rollT = k.isPlayer ? 1.1 : 0.4;
        if (k.isPlayer && this.mode === 'race') sound.item();
      },
      peelHit: (k, x, z, blocked) => {
        this.fx.sparks(x, 0.8, z, blocked ? C.blue : C.gold, 16, 6);
        if (!k.isPlayer || this.mode !== 'race') return;
        if (blocked) { sound.block(); this.cb.onEvent('¡ESCUDO ROTO!', '#38bdf8'); }
        else { sound.spin(); this.shake = 0.5; this.cb.onEvent('¡RESBALÓN!', '#ffd23f'); }
      },
      pad: k => { if (k.isPlayer && this.mode === 'race') { sound.boost(); this.cb.onEvent('¡ZONA TURBO!', '#ff7a1a'); } },
    });
    this.fx.update(dt);

    // Clasificación en tiempo real
    this.order.sort((a, b) => (a.finished && b.finished ? a.finishTime - b.finishTime : a.finished ? -1 : b.finished ? 1 : b.progress - a.progress));

    if (this.mode === 'race') {
      sound.engine(Math.min(1.3, Math.abs(player.speed) / MAX_V), true, player.boostT > 0);
      this.wrongShown = player.wrongT > 1;
    }
    if (this.mode === 'finish') {
      this.finishT += realDt;
      sound.engine(0.4, true, false);
      if (this.finishT > 3.5) this.endRace();
    }
    this.scenery.update(this.time, this.camera);
    this.updateCamera(dt, player);

    if (this.minimap && this.mode !== 'attract' && ++this.mapTick % 3 === 0) this.minimap.draw(this.track, this.karts, 0, this.time);
    this.hudClock -= realDt;
    if (this.hudClock <= 0 && this.mode !== 'attract') { this.hudClock = 0.08; this.emitHud(player); }
  }

  private onLap(k: Kart) {
    if (k.lap > 1) k.bestLap = Math.min(k.bestLap, this.raceT - k.lapStart);
    k.lapStart = this.raceT;
    if (k.lap > TOTAL_LAPS && !k.finished) {
      k.finished = true; k.finishTime = this.raceT;
      if (k.isPlayer && this.mode === 'race') {
        this.mode = 'finish'; this.finishT = 0;
        const pos = this.order.filter(o => o.finished).length;
        sound.finish(pos === 1);
        this.cb.onEvent(pos === 1 ? '¡VICTORIA!' : `¡META! ${pos}º`, pos <= 3 ? '#ffd23f' : '#ffffff');
        this.fx.burst(k.x, 2, k.z); this.fx.burst(k.x, 3, k.z);
      }
      return;
    }
    if (k.isPlayer && this.mode === 'race' && k.lap > 1) {
      sound.lap();
      if (k.lap === TOTAL_LAPS) { this.finalLap = true; this.cb.onEvent('¡ÚLTIMA VUELTA!', '#ff5ea8'); }
      else this.cb.onEvent(`VUELTA ${k.lap}/${TOTAL_LAPS}`, '#ffffff');
    }
  }

  private endRace() {
    const p = this.karts[0];
    const standings: Standing[] = this.order.map(k => ({ name: k.racer.name, color: k.racer.color, time: k.finished ? k.finishTime : null, player: k.isPlayer }));
    const pos = this.order.indexOf(p) + 1;
    this.mode = 'attract';
    this.karts.forEach(k => { if (!k.finished) { k.finished = true; k.finishTime = 9999 + this.order.indexOf(k); } });
    sound.engine(0, false, false); sound.stopMusic();
    this.cb.onFinish({ pos, time: p.finishTime, bestLap: p.bestLap, standings });
  }

  private collide() {
    const ks = this.karts;
    for (let i = 0; i < ks.length; i++) for (let j = i + 1; j < ks.length; j++) {
      const a = ks[i], b = ks[j], dx = b.x - a.x, dz = b.z - a.z, d2 = dx * dx + dz * dz;
      if (d2 > 5.8 || d2 < 1e-6) continue;
      const d = Math.sqrt(d2), push = (2.41 - d) / 2, nx = dx / d, nz = dz / d;
      a.x -= nx * push; a.z -= nz * push; b.x += nx * push; b.z += nz * push;
      const avg = (a.speed + b.speed) / 2;
      a.speed = a.speed * 0.8 + avg * 0.2 - 0.6; b.speed = b.speed * 0.8 + avg * 0.2 - 0.6;
      for (const [s, o] of [[a, b], [b, a]] as Array<[Kart, Kart]>) if (s.shieldT > 0 && o.shieldT <= 0 && o.spinT <= 0) { o.spinT = 0.8; }
      a.bump = b.bump = 0.5;
      if ((a.isPlayer || b.isPlayer) && this.mode === 'race') { this.shake = Math.max(this.shake, 0.18); this.fx.sparks(a.x + nx * 1.2, 0.8, a.z + nz * 1.2, C.spark, 5, 4); }
    }
  }

  private updateCamera(dt: number, p: Kart) {
    const cam = this.camera, k = 1 - Math.exp(-dt * 7);
    const hx = Math.sin(p.heading), hz = Math.cos(p.heading);
    const sN = Math.min(1.4, Math.abs(p.speed) / MAX_V);
    const want = new THREE.Vector3(), look = new THREE.Vector3();
    if (this.mode === 'attract' || this.mode === 'finish') {
      const att = this.mode === 'attract', t = att ? this.karts[3] : p;
      const a = this.time * (att ? 0.12 : 0.5), th = Math.sin(t.heading), tz = Math.cos(t.heading);
      if (att) want.set(t.x - th * 11 + tz * Math.sin(a) * 5, 5.5 + Math.sin(a * 0.7), t.z - tz * 11 - th * Math.sin(a) * 5);
      else want.set(t.x + Math.cos(a) * 9, 3.5, t.z + Math.sin(a) * 9);
      look.set(t.x + th * 4, 1.2, t.z + tz * 4);
      this.camera.fov += (60 - this.camera.fov) * k;
    } else {
      const back = 7.2 + sN * 1.6, up = 3.1 + sN * 0.3;
      want.set(p.x - hx * back, up, p.z - hz * back);
      look.set(p.x + hx * 5, 1.25, p.z + hz * 5);
      const fov = 64 + sN * 9 + (p.boostT > 0 ? 7 : 0);
      this.camera.fov += (fov - this.camera.fov) * Math.min(1, dt * 4);
    }
    const kk = this.snap ? 1 : this.mode === 'countdown' ? 1 - Math.exp(-dt * 2.5) : k;
    this.snap = false;
    this.camPos.lerp(want, kk); this.camLook.lerp(look, Math.min(1, kk * 1.6));
    cam.position.copy(this.camPos);
    if (this.shake > 0) {
      this.shake = Math.max(0, this.shake - dt * 1.6);
      cam.position.x += (Math.random() - 0.5) * this.shake; cam.position.y += (Math.random() - 0.5) * this.shake;
    }
    cam.lookAt(this.camLook);
    cam.updateProjectionMatrix();
  }

  private emitHud(p: Kart) {
    const lapT = this.mode === 'countdown' ? 0 : this.raceT - p.lapStart;
    this.cb.onHud({
      pos: this.order.indexOf(p) + 1, total: this.karts.length, lap: Math.max(1, Math.min(TOTAL_LAPS, p.lap)), laps: TOTAL_LAPS,
      time: this.mode === 'finish' ? p.finishTime : this.raceT, lapTime: lapT, bestLap: p.bestLap,
      kmh: Math.round(Math.abs(p.speed) * 3.6 * 1.25), speedN: Math.min(1, Math.abs(p.speed) / (MAX_V * 1.35)),
      item: p.item, rolling: p.rollT > 0, boost: p.boostT, shield: p.shieldT,
      drift: p.driftDir === 0 ? 0 : p.driftT > 1.7 ? 2 : p.driftT > 0.8 ? 1 : 0.5,
      countdown: this.mode === 'countdown' || (this.mode === 'race' && this.raceT < 0.9) ? this.cdShown : null,
      wrong: this.wrongShown, mode: this.mode,
    });
  }

  dispose() {
    cancelAnimationFrame(this.raf); this.ro.disconnect(); this.input.dispose();
    sound.engine(0, false, false); sound.stopMusic();
    this.track.dispose(); this.scenery.dispose(); this.items.dispose(); this.fx.dispose();
    this.karts.forEach(k => k.dispose());
    this.tags.forEach(t => { (t.material as THREE.SpriteMaterial).map?.dispose(); t.material.dispose(); });
    this.shadowTex.dispose(); this.shadowMat.dispose(); this.shadowGeo.dispose(); this.flameTex.dispose();
    this.renderer.dispose(); this.renderer.domElement.remove();
  }
}

// Partículas con pool fijo (polvo, chispas de derrape, estrellas, fuego) dibujadas como Points con shader propio.
import * as THREE from 'three';
import { rawColor } from './three-compat';

const VERT = `attribute vec3 aColor; attribute float aSize; attribute float aAlpha;
varying vec3 vC; varying float vA;
void main(){ vC = aColor; vA = aAlpha; vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * (320.0 / max(-mv.z, 0.5)); gl_Position = projectionMatrix * mv; }`;
const FRAG = `varying vec3 vC; varying float vA;
void main(){ vec2 d = gl_PointCoord - 0.5; float r = length(d); if (r > 0.5) discard;
  float a = smoothstep(0.5, 0.0, r) * vA; gl_FragColor = vec4(vC, a); }`;

class Pool {
  readonly points: THREE.Points;
  private pos: Float32Array; private col: Float32Array; private size: Float32Array; private alpha: Float32Array;
  private vel: Float32Array; private life: Float32Array; private max: Float32Array; private s0: Float32Array; private grow: Float32Array;
  private head = 0;
  constructor(private n: number, additive: boolean) {
    [this.pos, this.col, this.vel] = [0, 0, 0].map(() => new Float32Array(n * 3));
    [this.size, this.alpha, this.life, this.max, this.s0, this.grow] = [0, 0, 0, 0, 0, 0].map(() => new Float32Array(n));
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    g.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    g.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    g.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    const m = new THREE.ShaderMaterial({ vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending });
    this.points = new THREE.Points(g, m);
    this.points.frustumCulled = false;
  }
  emit(x: number, y: number, z: number, vx: number, vy: number, vz: number, c: THREE.Vector3, size: number, life: number, grow = 0) {
    const i = this.head; this.head = (this.head + 1) % this.n;
    this.pos.set([x, y, z], i * 3); this.vel.set([vx, vy, vz], i * 3); this.col.set([c.x, c.y, c.z], i * 3);
    this.life[i] = life; this.max[i] = life; this.s0[i] = size; this.grow[i] = grow;
  }
  update(dt: number, gravity: number) {
    for (let i = 0; i < this.n; i++) {
      if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
      this.life[i] -= dt;
      const k = i * 3, t = Math.max(0, this.life[i] / this.max[i]);
      this.vel[k + 1] -= gravity * dt;
      this.vel[k] *= 1 - dt * 1.5; this.vel[k + 2] *= 1 - dt * 1.5;
      this.pos[k] += this.vel[k] * dt; this.pos[k + 1] = Math.max(0.05, this.pos[k + 1] + this.vel[k + 1] * dt); this.pos[k + 2] += this.vel[k + 2] * dt;
      this.alpha[i] = Math.min(1, t * 1.6);
      this.size[i] = this.s0[i] * (1 + (1 - t) * this.grow[i]);
    }
    const g = this.points.geometry;
    (['position', 'aColor', 'aSize', 'aAlpha'] as const).forEach(a => { (g.getAttribute(a) as THREE.BufferAttribute).needsUpdate = true; });
  }
  clear() { this.life.fill(0); this.alpha.fill(0); }
  dispose() { this.points.geometry.dispose(); (this.points.material as THREE.Material).dispose(); }
}

export const C = {
  dust: rawColor('#d8c7a0'), smoke: rawColor('#e9ecf2'), grass: rawColor('#7fd36a'), snow: rawColor('#ffffff'),
  blue: rawColor('#5ad8ff'), orange: rawColor('#ffa31a'), fire: rawColor('#ff6a1a'), gold: rawColor('#ffe14d'),
  spark: rawColor('#fff3b0'), pink: rawColor('#ff5ea8'), green: rawColor('#3dff9a'),
};

export class Fx {
  readonly group = new THREE.Group();
  private soft = new Pool(260, false);
  private glow = new Pool(360, true);
  constructor() { this.group.add(this.soft.points, this.glow.points); }

  dust(x: number, z: number, c: THREE.Vector3, n = 1) {
    for (let i = 0; i < n; i++) this.soft.emit(x + (Math.random() - 0.5), 0.3, z + (Math.random() - 0.5), (Math.random() - 0.5) * 2, 1 + Math.random() * 1.5, (Math.random() - 0.5) * 2, c, 0.9, 0.8 + Math.random() * 0.5, 2.2);
  }
  sparks(x: number, y: number, z: number, c: THREE.Vector3, n: number, spd = 6) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2, s = spd * (0.4 + Math.random() * 0.8);
      this.glow.emit(x, y, z, Math.cos(a) * s, 2 + Math.random() * spd * 0.8, Math.sin(a) * s, c, 0.35 + Math.random() * 0.25, 0.4 + Math.random() * 0.4);
    }
  }
  burst(x: number, y: number, z: number) {
    const cols = [C.pink, C.gold, C.green, C.blue];
    for (let i = 0; i < 26; i++) {
      const a = Math.random() * Math.PI * 2, s = 3 + Math.random() * 6;
      this.glow.emit(x, y, z, Math.cos(a) * s, 3 + Math.random() * 6, Math.sin(a) * s, cols[i % 4], 0.5, 0.7 + Math.random() * 0.4);
    }
  }
  flame(x: number, z: number, hx: number, hz: number) {
    this.glow.emit(x - hx * 2.1 + (Math.random() - 0.5) * 0.5, 0.55, z - hz * 2.1 + (Math.random() - 0.5) * 0.5, -hx * 6, 0.6, -hz * 6, Math.random() < 0.5 ? C.fire : C.orange, 0.7, 0.25);
  }
  drift(x: number, z: number, c: THREE.Vector3) {
    this.glow.emit(x, 0.25, z, (Math.random() - 0.5) * 3, 1.5 + Math.random() * 2, (Math.random() - 0.5) * 3, c, 0.32, 0.3);
  }
  update(dt: number) { this.soft.update(dt, -0.6); this.glow.update(dt, 9); }
  clear() { this.soft.clear(); this.glow.clear(); }
  dispose() { this.soft.dispose(); this.glow.dispose(); }
}

// Entrada: teclado (flechas / WASD) escuchado en window + botones táctiles virtuales.
export interface VirtualPad { up: boolean; down: boolean; left: boolean; right: boolean; item: boolean; drift: boolean }

export class Input {
  private keys = new Set<string>();
  readonly virtual: VirtualPad = { up: false, down: false, left: false, right: false, item: false, drift: false };
  private prevItem = false;

  private onDown = (e: KeyboardEvent) => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  constructor() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  private any(...codes: string[]) { return codes.some(c => this.keys.has(c)); }
  get up() { return this.virtual.up || this.any('ArrowUp', 'KeyW'); }
  get down() { return this.virtual.down || this.any('ArrowDown', 'KeyS'); }
  get steer() {
    return (this.virtual.right || this.any('ArrowRight', 'KeyD') ? 1 : 0) - (this.virtual.left || this.any('ArrowLeft', 'KeyA') ? 1 : 0);
  }
  get drift() { return this.virtual.drift || this.any('ShiftLeft', 'ShiftRight', 'KeyX', 'KeyK'); }
  /** Pulsación nueva del botón de objeto (flanco de subida). */
  itemPressed() {
    const now = this.virtual.item || this.any('Space', 'KeyE', 'KeyJ');
    const edge = now && !this.prevItem;
    this.prevItem = now;
    return edge;
  }
  reset() { this.keys.clear(); Object.assign(this.virtual, { up: false, down: false, left: false, right: false, item: false, drift: false }); }

  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

// Objetos en pista: cajas sorpresa (turbo, cáscara, escudo), cáscaras soltadas y zonas turbo.
import * as THREE from 'three';
import { ItemId } from './config';
import { Kart } from './karts';
import { canvasTexture, lin } from './three-compat';
import { Track } from './track';

interface Box { mesh: THREE.Mesh; x: number; z: number; t: number }
interface Peel { mesh: THREE.Group; x: number; z: number; life: number; owner: number; safe: number; active: boolean }
interface Pad { x: number; z: number; hx: number; hz: number; idx: number }

export interface ItemEvents {
  pickup(k: Kart, x: number, z: number): void;
  peelHit(k: Kart, x: number, z: number, blocked: boolean): void;
  pad(k: Kart): void;
}

export class Items {
  readonly group = new THREE.Group();
  private boxes: Box[] = [];
  private peels: Peel[] = [];
  private pads: Pad[] = [];
  private padMat: THREE.MeshBasicMaterial;
  private trash: Array<{ dispose(): void }> = [];

  constructor(private track: Track) {
    // Caja sorpresa con "?" brillante
    const qTex = canvasTexture(128, 128, g => {
      const gr = g.createLinearGradient(0, 0, 128, 128);
      gr.addColorStop(0, '#ff5ea8'); gr.addColorStop(0.35, '#ffd23f'); gr.addColorStop(0.7, '#3dff9a'); gr.addColorStop(1, '#3db8ff');
      g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
      g.strokeStyle = 'rgba(255,255,255,0.95)'; g.lineWidth = 10; g.strokeRect(5, 5, 118, 118);
      g.font = '900 84px Arial'; g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillStyle = 'rgba(0,0,0,0.25)'; g.fillText('?', 68, 72); g.fillStyle = '#fff'; g.fillText('?', 64, 68);
    });
    const boxMat = new THREE.MeshBasicMaterial({ map: qTex, transparent: true, opacity: 0.92 }), boxGeo = new THREE.BoxGeometry(1.5, 1.5, 1.5), N = track.N;
    this.trash.push(qTex, boxMat, boxGeo);
    for (const f of [0.07, 0.4, 0.72]) for (const lat of [-5.2, -1.75, 1.75, 5.2]) {
      const p = track.point(f * N, lat), mesh = new THREE.Mesh(boxGeo, boxMat);
      mesh.position.set(p.x, 1.3, p.z); this.group.add(mesh);
      this.boxes.push({ mesh, x: p.x, z: p.z, t: 0 });
    }

    // Zonas turbo: flechas emisivas sobre el asfalto
    const padTex = canvasTexture(128, 160, g => {
      g.fillStyle = 'rgba(255,120,20,0.35)'; g.fillRect(0, 0, 128, 160);
      g.strokeStyle = '#ffe14d'; g.lineWidth = 6; g.strokeRect(3, 3, 122, 154);
      g.fillStyle = '#fff6b0';
      for (let i = 0; i < 3; i++) { const y = 20 + i * 45; g.beginPath(); g.moveTo(14, y + 34); g.lineTo(64, y); g.lineTo(114, y + 34); g.lineTo(98, y + 42); g.lineTo(64, y + 18); g.lineTo(30, y + 42); g.closePath(); g.fill(); }
    });
    this.padMat = new THREE.MeshBasicMaterial({ map: padTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
    const padGeo = new THREE.PlaneGeometry(4.2, 5.4);
    this.trash.push(padTex, this.padMat, padGeo);
    for (const [f, lat] of [[0.31, -3.5], [0.6, 3.5], [0.88, 0]] as Array<[number, number]>) {
      const i = Math.round(f * N), p = track.point(i, lat), m = new THREE.Mesh(padGeo, this.padMat);
      m.rotation.set(-Math.PI / 2, track.heading(i) + Math.PI, 0, 'YXZ'); m.position.set(p.x, 0.07, p.z); this.group.add(m);
      this.pads.push({ x: p.x, z: p.z, hx: track.tx[i], hz: track.tz[i], idx: i });
    }

    // Pool de cáscaras de plátano
    const peelMat = new THREE.MeshLambertMaterial({ color: lin('#ffd23f') }), tipMat = new THREE.MeshLambertMaterial({ color: lin('#6b4a1f') });
    const petal = new THREE.ConeGeometry(0.32, 1.1, 6), tip = new THREE.SphereGeometry(0.2, 8, 6);
    this.trash.push(peelMat, tipMat, petal, tip);
    for (let i = 0; i < 14; i++) {
      const g = new THREE.Group();
      for (let k = 0; k < 4; k++) {
        const pm = new THREE.Mesh(petal, peelMat), a = (k / 4) * Math.PI * 2;
        pm.position.set(Math.cos(a) * 0.45, 0.25, Math.sin(a) * 0.45); pm.rotation.set(Math.sin(a) * 1.25, 0, -Math.cos(a) * 1.25); g.add(pm);
      }
      const t = new THREE.Mesh(tip, tipMat); t.position.y = 0.55; g.add(t);
      g.visible = false; this.group.add(g);
      this.peels.push({ mesh: g, x: 0, z: 0, life: 0, owner: -1, safe: 0, active: false });
    }
  }

  get peelList() { return this.peels; }

  reset() {
    for (const b of this.boxes) { b.t = 0; b.mesh.visible = true; }
    for (const p of this.peels) { p.active = false; p.mesh.visible = false; }
  }

  dropPeel(k: Kart) {
    const p = this.peels.find(q => !q.active) ?? this.peels.reduce((a, b) => (a.life < b.life ? a : b));
    p.x = k.x - Math.sin(k.heading) * 3.2; p.z = k.z - Math.cos(k.heading) * 3.2;
    p.life = 45; p.owner = k.id; p.safe = 0.8; p.active = true;
    p.mesh.visible = true; p.mesh.position.set(p.x, 0, p.z); p.mesh.rotation.y = Math.random() * 6;
  }

  /** Objeto aleatorio ponderado por posición: los últimos reciben más turbo. */
  static roll(pos: number, total: number): ItemId {
    const back = (pos - 1) / Math.max(1, total - 1), r = Math.random(), wT = 0.25 + back * 0.45, wC = 0.4 - back * 0.2;
    return r < wT ? 'turbo' : r < wT + wC ? 'cascara' : 'escudo';
  }

  update(dt: number, time: number, karts: Kart[], ev: ItemEvents) {
    for (const b of this.boxes) {
      if (b.t > 0) { b.t -= dt; if (b.t > 0) continue; b.mesh.visible = true; }
      b.mesh.rotation.set(time * 0.9, time * 1.3, 0);
      b.mesh.position.y = 1.3 + Math.sin(time * 2.5 + b.x) * 0.22;
      for (const k of karts) {
        const dx = k.x - b.x, dz = k.z - b.z;
        if (dx * dx + dz * dz < 4.2) { b.t = 3.2; b.mesh.visible = false; ev.pickup(k, b.x, b.z); break; }
      }
    }
    for (const p of this.peels) {
      if (!p.active) continue;
      p.life -= dt; p.safe -= dt;
      if (p.life <= 0) { p.active = false; p.mesh.visible = false; continue; }
      p.mesh.rotation.y += dt * 0.4;
      for (const k of karts) {
        if (k.spinT > 0 || (p.safe > 0 && k.id === p.owner)) continue;
        const dx = k.x - p.x, dz = k.z - p.z;
        if (dx * dx + dz * dz < 2.6) {
          p.active = false; p.mesh.visible = false;
          const blocked = k.shieldT > 0;
          if (blocked) k.shieldT = 0; else { k.spinT = 1.25; k.boostT = 0; }
          ev.peelHit(k, p.x, p.z, blocked); break;
        }
      }
    }
    for (const pd of this.pads) {
      for (const k of karts) {
        const dx = k.x - pd.x, dz = k.z - pd.z;
        const along = dx * pd.hx + dz * pd.hz, side = -dx * pd.hz + dz * pd.hx;
        if (Math.abs(along) < 2.8 && Math.abs(side) < 2.3 && k.boostT < 0.9) { k.boostT = 1.0; ev.pad(k); }
      }
    }
    this.padMat.opacity = 0.75 + Math.sin(time * 8) * 0.25;
  }

  /** ¿Hay una cáscara delante de este kart? (para que la IA la esquive) */
  peelAhead(k: Kart, track: Track): number | null {
    for (const p of this.peels) {
      if (!p.active) continue;
      const dx = p.x - k.x, dz = p.z - k.z;
      const f = dx * Math.sin(k.heading) + dz * Math.cos(k.heading);
      if (f > 2 && f < 22) return track.nearest(p.x, p.z, k.idx).lat;
    }
    return null;
  }

  dispose() { this.trash.forEach(t => t.dispose()); this.trash = []; this.group.clear(); }
}

// Kart: modelo 3D procedural + física arcade (aceleración, giro, derrape con mini-turbo, fuera de pista, muros).
import * as THREE from 'three';
import { ItemId, Racer } from './config';
import { canvasTexture, lin } from './three-compat';
import { CURB_W, ROAD_W, Track, WALL_OFF } from './track';

export const MAX_V = 31;      // m/s
export const BOOST_V = 43;

export interface Controls { throttle: number; brake: number; steer: number; drift: boolean }

export interface KartEvents {
  wall(k: Kart, impact: number): void;
  miniTurbo(k: Kart, level: number): void;
}

export class Kart {
  readonly mesh = new THREE.Group();
  readonly body = new THREE.Group();
  private wheels: THREE.Mesh[] = [];
  private fronts: THREE.Group[] = [];
  readonly shield: THREE.Mesh;
  readonly flame: THREE.Sprite;
  private trash: Array<{ dispose(): void }> = [];

  x = 0; z = 0; heading = 0; speed = 0; steerVis = 0;
  idx = 0; lat = 0; along = 0; lap = 0; half = true; progress = 0;
  finished = false; finishTime = 0; lapStart = 0; bestLap = Infinity;
  item: ItemId | null = null; rollT = 0;
  boostT = 0; shieldT = 0; spinT = 0; spinA = 0; offroad = false;
  driftDir = 0; driftT = 0; wrongT = 0; bump = 0;
  // IA
  lane = 0; laneT = 0; skill = 1; itemT = 0;

  constructor(readonly racer: Racer, readonly id: number, readonly isPlayer: boolean, flameTex: THREE.Texture) {
    const ph = (color: string, shininess = 60) => new THREE.MeshPhongMaterial({ color: lin(color), shininess, specular: lin('#555555') });
    const paint = ph(racer.color, 90), dark = ph('#22242e', 20), accent = ph(racer.accent), rim = ph('#d9dde6', 100);
    const tire = new THREE.MeshLambertMaterial({ color: lin('#15161c') }), visor = ph('#0b0f1a', 120);
    this.trash.push(paint, dark, accent, tire, rim, visor);
    const add = (geo: THREE.BufferGeometry, m: THREE.Material, x: number, y: number, z: number, rx = 0) => {
      const me = new THREE.Mesh(geo, m); me.position.set(x, y, z); me.rotation.x = rx; this.body.add(me); this.trash.push(geo); return me;
    };
    const B = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
    add(B(1.5, 0.32, 2.5), paint, 0, 0.45, 0);              // chasis
    add(B(1.1, 0.28, 0.9), paint, 0, 0.42, 1.55);           // morro
    add(B(1.9, 0.18, 0.4), accent, 0, 0.36, 1.95);          // alerón delantero
    for (const sx of [-1, 1]) { add(B(0.42, 0.34, 1.5), dark, sx * 0.92, 0.42, -0.1); add(B(0.1, 0.5, 0.2), dark, sx * 0.6, 0.98, -1.2); }
    add(B(0.9, 0.55, 0.25), dark, 0, 0.85, -0.55);          // respaldo
    add(B(1.7, 0.1, 0.5), accent, 0, 1.25, -1.25);          // alerón trasero
    add(new THREE.CylinderGeometry(0.32, 0.38, 0.6, 8), paint, 0, 0.95, -0.2);   // piloto
    add(new THREE.SphereGeometry(0.36, 14, 10), accent, 0, 1.45, -0.15);         // casco
    add(B(0.5, 0.18, 0.2), visor, 0, 1.47, 0.16);
    add(new THREE.TorusGeometry(0.22, 0.05, 6, 12), dark, 0, 1.0, 0.45, -0.9);  // volante
    // Ruedas (las delanteras giran con la dirección)
    const wg = new THREE.CylinderGeometry(0.42, 0.42, 0.42, 14), rg = new THREE.CylinderGeometry(0.22, 0.22, 0.44, 8);
    wg.rotateZ(Math.PI / 2); rg.rotateZ(Math.PI / 2); this.trash.push(wg, rg);
    for (const [x, z] of [[-0.98, 1.05], [0.98, 1.05], [-1.0, -0.95], [1.0, -0.95]]) {
      const pivot = new THREE.Group(), w = new THREE.Mesh(wg, tire);
      pivot.position.set(x, 0.42, z); w.add(new THREE.Mesh(rg, rim));
      if (z < 0) w.scale.set(1.25, 1.08, 1.08); else this.fronts.push(pivot);
      pivot.add(w); this.body.add(pivot); this.wheels.push(w);
    }
    // Dorsal
    const num = canvasTexture(64, 64, g => {
      g.fillStyle = '#fff'; g.beginPath(); g.arc(32, 32, 30, 0, 7); g.fill();
      g.fillStyle = '#111'; g.font = '900 40px Arial'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(String(id + 1), 32, 34);
    });
    const numMat = new THREE.MeshBasicMaterial({ map: num, transparent: true });
    add(new THREE.PlaneGeometry(0.62, 0.62), numMat, 0, 0.62, 2.01);
    // Escudo (burbuja) y llama de turbo
    const shMat = new THREE.MeshBasicMaterial({ color: lin('#5ad8ff'), transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false });
    this.shield = new THREE.Mesh(new THREE.IcosahedronGeometry(2.1, 1), shMat);
    this.shield.position.y = 0.9; this.shield.visible = false;
    const flMat = new THREE.SpriteMaterial({ map: flameTex, color: lin('#ffb347'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true });
    this.flame = new THREE.Sprite(flMat); this.flame.position.set(0, 0.6, -1.7); this.flame.visible = false;
    this.trash.push(num, numMat, shMat, this.shield.geometry, flMat);
    this.mesh.add(this.body, this.shield, this.flame);
    this.mesh.scale.setScalar(1.15);
  }

  place(track: Track, idx: number, lat: number) {
    const p = track.point(idx, lat);
    this.x = p.x; this.z = p.z; this.heading = track.heading(idx);
    this.idx = track.wrap(idx); this.speed = 0;
    this.lap = 0; this.half = true; this.finished = false; this.bestLap = Infinity;
    this.item = null; this.rollT = 0; this.boostT = 0; this.shieldT = 0; this.spinT = 0; this.driftDir = 0; this.driftT = 0;
    const n = track.nearest(this.x, this.z, this.idx);
    this.along = n.along; this.lat = n.lat; this.progress = n.along - track.length;
    this.sync(0, 0);
  }

  /** Avanza la física un paso. Devuelve true si cruzó la meta (nueva vuelta). */
  step(dt: number, c: Controls, track: Track, ev: KartEvents, speedK = 1): boolean {
    this.boostT = Math.max(0, this.boostT - dt); this.shieldT = Math.max(0, this.shieldT - dt);
    const boosting = this.boostT > 0;
    let top = (boosting ? BOOST_V : MAX_V) * speedK;
    this.offroad = Math.abs(this.lat) > ROAD_W / 2 + CURB_W * 0.6;
    if (this.offroad && !boosting) top *= 0.52;

    if (this.spinT > 0) {
      this.spinT -= dt; this.spinA += dt * 14 * Math.min(1, this.spinT + 0.3);
      this.speed *= Math.exp(-2.6 * dt); this.driftDir = 0; this.driftT = 0;
    } else {
      this.spinA = 0;
      if (c.throttle > 0 || boosting) {
        const acc = this.speed < top ? (boosting ? 30 : 15 + 10 * (1 - this.speed / MAX_V)) : -14;
        this.speed = Math.min(Math.max(this.speed + acc * dt, -10), Math.max(top, this.speed - 14 * dt));
      } else if (c.brake > 0) {
        this.speed = Math.max(-9, this.speed - (this.speed > 0 ? 34 : 12) * dt);
      } else {
        this.speed -= Math.sign(this.speed) * Math.min(Math.abs(this.speed), 7 * dt);
      }
      if (this.speed > top) this.speed = Math.max(top, this.speed - 22 * dt);

      // Derrape: al soltar suelta un mini-turbo según la carga
      const fast = this.speed > 13;
      if (c.drift && fast && Math.abs(c.steer) > 0.2 && this.driftDir === 0) { this.driftDir = Math.sign(c.steer); this.driftT = 0; }
      if (this.driftDir !== 0) {
        if (!c.drift || !fast) {
          const lvl = this.driftT > 1.7 ? 2 : this.driftT > 0.8 ? 1 : 0;
          if (lvl > 0 && fast) { this.boostT = Math.max(this.boostT, lvl === 2 ? 1.2 : 0.65); ev.miniTurbo(this, lvl); }
          this.driftDir = 0; this.driftT = 0;
        } else this.driftT += dt * (1 + Math.max(0, c.steer * this.driftDir) * 0.8);
      }
      const grip = Math.min(1, Math.abs(this.speed) / 7) * Math.sign(this.speed || 1);
      const steer = this.driftDir !== 0 ? this.driftDir * (0.75 + 0.55 * c.steer * this.driftDir) : c.steer;
      const rate = (this.driftDir !== 0 ? 2.15 : 1.85) * (1 - Math.min(0.35, Math.abs(this.speed) / 120));
      this.heading -= steer * rate * grip * dt;
      this.steerVis += (c.steer - this.steerVis) * Math.min(1, dt * 10);
    }

    const prevIdx = this.idx;
    this.x += Math.sin(this.heading) * this.speed * dt;
    this.z += Math.cos(this.heading) * this.speed * dt;
    let n = track.nearest(this.x, this.z, this.idx);
    // Muros laterales
    const lim = WALL_OFF - 1.3;
    if (Math.abs(n.lat) > lim) {
      const push = Math.abs(n.lat) - lim, s = Math.sign(n.lat);
      this.x -= track.rx(n.idx) * push * s; this.z -= track.rz(n.idx) * push * s;
      const fx = Math.sin(this.heading), fz = Math.cos(this.heading);
      const into = (fx * track.rx(n.idx) + fz * track.rz(n.idx)) * s;
      if (into > 0.05 && this.speed > 4) { ev.wall(this, this.speed * into); this.speed *= 1 - Math.min(0.55, into * 0.8); }
      // Redirige suavemente a lo largo del muro
      const th = track.heading(n.idx) + (this.speed < 0 ? Math.PI : 0);
      let d = th - this.heading; d = Math.atan2(Math.sin(d), Math.cos(d));
      if (Math.abs(d) < 1.3) this.heading += d * Math.min(1, dt * 6);
      n = track.nearest(this.x, this.z, n.idx);
    }
    this.idx = n.idx; this.lat = n.lat; this.along = n.along;

    // Vueltas: hay que pasar por la mitad del circuito para validar
    const N = track.N; let crossed = false;
    if (this.idx > N * 0.4 && this.idx < N * 0.6) this.half = true;
    if (prevIdx > N * 0.85 && this.idx < N * 0.15) {
      if (this.half) { this.lap++; this.half = false; crossed = true; } else this.lap++;
    } else if (prevIdx < N * 0.15 && this.idx > N * 0.85) { this.lap--; }
    this.progress = (this.lap - 1) * track.length + this.along;

    const fwd = Math.sin(this.heading) * track.tx[this.idx] + Math.cos(this.heading) * track.tz[this.idx];
    this.wrongT = fwd < -0.35 && Math.abs(this.speed) > 3 ? this.wrongT + dt : 0;
    return crossed;
  }

  /** Actualiza el modelo 3D a partir del estado. */
  sync(dt: number, time: number) {
    this.mesh.position.set(this.x, 0, this.z); this.mesh.rotation.y = this.heading + this.spinA;
    this.body.rotation.y += (this.driftDir * 0.38 - this.body.rotation.y) * Math.min(1, dt * 8);
    this.body.rotation.z = -this.steerVis * Math.min(1, this.speed / MAX_V) * 0.06 + (this.offroad ? Math.sin(time * 40) * 0.025 : 0);
    this.body.position.y = this.offroad ? Math.abs(Math.sin(time * 31)) * 0.06 : 0;
    this.bump = Math.max(0, this.bump - dt * 3);
    this.body.rotation.x = -Math.min(0.06, Math.max(-0.05, this.boostT > 0 ? 0.05 : 0)) + this.bump * 0.2;
    for (const w of this.wheels) w.rotation.x += this.speed * dt / 0.42;
    for (const f of this.fronts) f.rotation.y = -this.steerVis * 0.45;
    this.shield.visible = this.shieldT > 0;
    if (this.shield.visible) {
      this.shield.rotation.y = time * 1.6;
      (this.shield.material as THREE.MeshBasicMaterial).opacity = 0.22 + Math.sin(time * 9) * 0.06 + (this.shieldT < 1.5 ? Math.sin(time * 30) * 0.12 : 0);
    }
    this.flame.visible = this.boostT > 0;
    if (this.flame.visible) { const s = 1.2 + Math.random() * 0.7; this.flame.scale.set(s, s, 1); }
  }

  dispose() { this.trash.forEach(t => t.dispose()); this.trash = []; }
}

// Minimapa 2D del circuito con la posición de cada kart.
import { Kart } from './karts';
import { Track } from './track';

export class Minimap {
  private pts: Array<[number, number]> = [];
  private ctx: CanvasRenderingContext2D | null;
  constructor(private canvas: HTMLCanvasElement) { this.ctx = canvas.getContext('2d'); }

  setTrack(t: Track) { this.pts = t.minimapPoints(6); }

  draw(track: Track, karts: Kart[], playerId: number, time: number) {
    const g = this.ctx, c = this.canvas;
    if (!g || !this.pts.length) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(1, Math.round(c.clientWidth * dpr)), h = Math.max(1, Math.round(c.clientHeight * dpr));
    if (c.width !== w || c.height !== h) { c.width = w; c.height = h; }
    g.clearRect(0, 0, w, h);
    const pad = 10 * dpr, s = Math.min(w, h) - pad * 2, ox = (w - s) / 2, oy = (h - s) / 2;
    const P = (u: number, v: number): [number, number] => [ox + u * s, oy + v * s];
    g.lineJoin = 'round'; g.lineCap = 'round';
    g.beginPath();
    this.pts.forEach(([u, v], i) => { const [x, y] = P(u, v); if (i) g.lineTo(x, y); else g.moveTo(x, y); });
    g.closePath();
    g.strokeStyle = 'rgba(255,255,255,0.95)'; g.lineWidth = 9 * dpr; g.stroke();
    g.strokeStyle = '#2b2f3d'; g.lineWidth = 5 * dpr; g.stroke();
    // Línea de meta
    const [sx, sy] = P(this.pts[0][0], this.pts[0][1]);
    g.fillStyle = '#ffffff'; g.fillRect(sx - 4 * dpr, sy - 4 * dpr, 8 * dpr, 8 * dpr);
    g.fillStyle = '#111'; g.fillRect(sx - 4 * dpr, sy - 4 * dpr, 4 * dpr, 4 * dpr); g.fillRect(sx, sy, 4 * dpr, 4 * dpr);
    const r = track.radius * 1.05;
    const order = [...karts].sort((a, b) => (a.id === playerId ? 1 : 0) - (b.id === playerId ? 1 : 0));
    for (const k of order) {
      const [x, y] = P((k.x - track.center.x) / r * 0.5 + 0.5, (k.z - track.center.y) / r * 0.5 + 0.5);
      const me = k.id === playerId, rad = (me ? 6 : 4.2) * dpr;
      if (me) { g.fillStyle = `rgba(255,255,255,${0.35 + Math.sin(time * 8) * 0.2})`; g.beginPath(); g.arc(x, y, rad + 5 * dpr, 0, 7); g.fill(); }
      g.fillStyle = k.racer.color; g.strokeStyle = '#fff'; g.lineWidth = 2 * dpr;
      g.beginPath(); g.arc(x, y, rad, 0, 7); g.fill(); g.stroke();
    }
  }
}

// Escenario del circuito: cielo, suelo, colinas/mesetas/picos, vegetación, nubes, pórtico de meta, grada y banderas.
import * as THREE from 'three';
import { Theme } from './config';
import { mulberry, ROAD_W, Track, WALL_OFF } from './track';
import { canvasTexture, lin, rawColor } from './three-compat';

const SKY_FRAG = `uniform vec3 top; uniform vec3 bot; uniform vec3 sun; uniform vec3 sunDir; varying vec3 vD;
void main(){ vec3 d = normalize(vD); float h = clamp(d.y, 0.0, 1.0);
  vec3 c = mix(bot, top, pow(h, 0.55)); float s = max(dot(d, sunDir), 0.0);
  c += sun * (pow(s, 900.0) * 1.2 + pow(s, 24.0) * 0.35); gl_FragColor = vec4(c, 1.0); }`;

export class Scenery {
  readonly group = new THREE.Group();
  readonly sky: THREE.Mesh;
  readonly sunDir: THREE.Vector3;
  private trash: Array<{ dispose(): void }> = [];
  private clouds: THREE.Sprite[] = [];

  constructor(private track: Track, private th: Theme) {
    const rnd = mulberry(th.seed * 31 + 5);
    this.sunDir = new THREE.Vector3(-0.55, th.hillKind === 'mesa' ? 0.16 : 0.42, -0.72).normalize();
    // Cielo degradado con halo solar (colores sRGB crudos: igual en r128 y r170)
    const skyMat = new THREE.ShaderMaterial({
      uniforms: { top: { value: rawColor(th.skyTop) }, bot: { value: rawColor(th.skyBottom) }, sun: { value: rawColor(th.sun) }, sunDir: { value: this.sunDir } },
      vertexShader: 'varying vec3 vD; void main(){ vD = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader: SKY_FRAG, side: THREE.BackSide, depthWrite: false, fog: false,
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(1400, 32, 16), skyMat);
    this.sky.renderOrder = -10;
    this.group.add(this.sky); this.trash.push(skyMat, this.sky.geometry);
    // Suelo con textura de ruido
    const groundTex = canvasTexture(256, 256, g => {
      g.fillStyle = th.ground; g.fillRect(0, 0, 256, 256);
      for (let i = 0; i < 3000; i++) { g.fillStyle = Math.random() < 0.5 ? 'rgba(0,0,0,0.07)' : 'rgba(255,255,255,0.08)'; g.fillRect(Math.random() * 256, Math.random() * 256, 3, 3); }
    }, true);
    groundTex.repeat.set(90, 90); this.trash.push(groundTex);
    const ground = this.add(new THREE.Mesh(new THREE.PlaneGeometry(3000, 3000), new THREE.MeshLambertMaterial({ map: groundTex })));
    ground.rotation.x = -Math.PI / 2; ground.position.set(track.center.x, -0.02, track.center.y);
    this.buildHills(rnd); this.buildFlora(rnd); this.buildClouds(rnd);
    this.buildGantry(); this.buildStand(); this.buildFlags();
  }

  private add<T extends THREE.Mesh>(m: T) {
    this.group.add(m); this.trash.push(m.geometry, m.material as THREE.Material);
    return m;
  }
  private phong(color: string) { return new THREE.MeshPhongMaterial({ color: lin(color), flatShading: true, shininess: 0 }); }

  private buildHills(rnd: () => number) {
    const th = this.th, kind = th.hillKind, n = 34, peak = kind === 'peak';
    const geo = kind === 'hill' ? new THREE.SphereGeometry(1, 9, 6) : kind === 'mesa' ? new THREE.CylinderGeometry(0.75, 1, 1, 7) : new THREE.ConeGeometry(1, 1, 6);
    const im = this.add(new THREE.InstancedMesh(geo, this.phong(peak ? '#7d93b8' : '#ffffff'), n));
    const caps = peak ? this.add(new THREE.InstancedMesh(geo, this.phong('#ffffff'), n)) : null;
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), c = new THREE.Color(), base = lin(th.hill), up = new THREE.Vector3(0, 1, 0);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + rnd() * 0.15, dist = this.track.radius * 1.25 + 160 + rnd() * 260;
      const r = 70 + rnd() * 90, h = kind === 'hill' ? r * (0.35 + rnd() * 0.25) : kind === 'mesa' ? 50 + rnd() * 70 : 120 + rnd() * 140;
      const p = new THREE.Vector3(this.track.center.x + Math.cos(a) * dist * 1.2, kind === 'mesa' ? h / 2 : peak ? h / 2 - 4 : -4, this.track.center.y + Math.sin(a) * dist);
      q.setFromAxisAngle(up, rnd() * 6);
      im.setMatrixAt(i, m4.compose(p, q, new THREE.Vector3(r, h, r)));
      if (!peak) im.setColorAt(i, c.copy(base).offsetHSL((rnd() - 0.5) * 0.04, 0, (rnd() - 0.5) * 0.12));
      // Gorro de nieve: cono más pequeño en la cima
      if (caps) caps.setMatrixAt(i, m4.compose(p.setY(p.y + h * 0.32), q, new THREE.Vector3(r * 0.36, h * 0.36, r * 0.36)));
    }
  }

  private buildFlora(rnd: () => number) {
    const th = this.th, t = this.track, spots: THREE.Vector3[] = [];
    for (let tries = 0; spots.length < 230 && tries < 3000; tries++) {
      const a = rnd() * Math.PI * 2, r = rnd() * (t.radius * 1.35 + 120);
      const x = t.center.x + Math.cos(a) * r * 1.2, z = t.center.y + Math.sin(a) * r;
      if (t.nearestGlobal(x, z).d > WALL_OFF + 5) spots.push(new THREE.Vector3(x, 0, z));
    }
    const cactus = th.flora === 'cactus';
    const trunkGeo = cactus ? new THREE.CylinderGeometry(0.55, 0.7, 6, 8) : new THREE.CylinderGeometry(0.35, 0.55, 3, 6);
    const topGeo = th.flora === 'round' ? new THREE.IcosahedronGeometry(2.6, 0) : th.flora === 'pine' ? new THREE.ConeGeometry(2.6, 7, 7) : new THREE.CylinderGeometry(0.42, 0.5, 3, 7);
    const trunks = this.add(new THREE.InstancedMesh(trunkGeo, new THREE.MeshLambertMaterial({ color: lin(cactus ? th.foliage[0] : th.trunk) }), spots.length));
    const tops = this.add(new THREE.InstancedMesh(topGeo, this.phong('#ffffff'), spots.length));
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), c = new THREE.Color(), e = new THREE.Euler();
    spots.forEach((p, i) => {
      const s = 0.8 + rnd() * 0.7, S = new THREE.Vector3(s, s, s);
      q.setFromEuler(e.set(0, rnd() * 6, 0));
      trunks.setMatrixAt(i, m4.compose(new THREE.Vector3(p.x, (cactus ? 3 : 1.5) * s, p.z), q, S));
      if (cactus) { q.setFromEuler(e.set(0, rnd() * 6, 0.9)); m4.compose(new THREE.Vector3(p.x + 0.6 * s, 3.4 * s, p.z), q, S); } // brazo del cactus
      else m4.compose(new THREE.Vector3(p.x, (th.flora === 'pine' ? 5.5 : 4.4) * s, p.z), q, S.setY(s * (0.9 + rnd() * 0.3)));
      tops.setMatrixAt(i, m4);
      tops.setColorAt(i, c.set(th.foliage[Math.floor(rnd() * th.foliage.length)]).convertSRGBToLinear());
    });
  }

  private buildClouds(rnd: () => number) {
    const tex = canvasTexture(128, 64, g => {
      for (let i = 0; i < 9; i++) {
        const x = 24 + Math.random() * 80, y = 30 + Math.random() * 14, r = 14 + Math.random() * 14, gr = g.createRadialGradient(x, y, 0, x, y, r);
        gr.addColorStop(0, 'rgba(255,255,255,0.95)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
        g.fillStyle = gr; g.fillRect(0, 0, 128, 64);
      }
    });
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, fog: false, opacity: 0.9 });
    this.trash.push(tex, mat);
    for (let i = 0; i < 16; i++) {
      const s = new THREE.Sprite(mat), a = rnd() * Math.PI * 2, d = 300 + rnd() * 500;
      s.position.set(this.track.center.x + Math.cos(a) * d, 90 + rnd() * 90, this.track.center.y + Math.sin(a) * d);
      s.scale.set(120 + rnd() * 80, 50 + rnd() * 25, 1);
      this.clouds.push(s); this.group.add(s);
    }
  }

  private box(g: THREE.Group, w: number, h: number, d: number, m: THREE.Material | THREE.Material[], x: number, y: number, z = 0) {
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
    b.position.set(x, y, z); g.add(b); this.trash.push(b.geometry);
    return b;
  }

  private buildGantry() {
    const t = this.track, g = new THREE.Group(), half = ROAD_W / 2 + 1.6;
    g.position.copy(t.point(0)); g.rotation.y = t.heading(0);
    const metal = new THREE.MeshPhongMaterial({ color: lin('#2b2f3d'), shininess: 60 });
    const banner = canvasTexture(1024, 128, c => {
      const gr = c.createLinearGradient(0, 0, 1024, 0);
      gr.addColorStop(0, '#ff2d3d'); gr.addColorStop(0.5, '#ffb21a'); gr.addColorStop(1, '#ff2d3d');
      c.fillStyle = gr; c.fillRect(0, 0, 1024, 128);
      for (let x = 0; x < 64; x++) { c.fillStyle = x % 2 ? '#111' : '#fff'; c.fillRect(x * 16, 0, 16, 12); c.fillRect(x * 16 + (x % 2 ? -16 : 0), 116, 16, 12); }
      c.font = 'italic 900 78px Arial'; c.textAlign = 'center'; c.textBaseline = 'middle';
      c.fillStyle = 'rgba(0,0,0,0.35)'; c.fillText('KART RALLY · META', 516, 70);
      c.fillStyle = '#fff'; c.fillText('KART RALLY · META', 512, 66);
    });
    const bm = new THREE.MeshBasicMaterial({ map: banner }), lightGeo = new THREE.SphereGeometry(0.32, 10, 8);
    const red = new THREE.MeshBasicMaterial({ color: lin('#ff3030') }), green = new THREE.MeshBasicMaterial({ color: lin('#3dff6a') });
    this.trash.push(metal, banner, bm, lightGeo, red, green);
    for (const sx of [-1, 1]) this.box(g, 1, 8, 1, metal, sx * half, 4);
    this.box(g, half * 2 + 1, 2.2, 0.6, [metal, metal, metal, metal, bm, bm], 0, 8);
    // Semáforo
    for (let i = 0; i < 4; i++) { const l = new THREE.Mesh(lightGeo, i < 3 ? red : green); l.position.set(-2.4 + i * 1.6, 6.4, 0); g.add(l); }
    this.group.add(g);
  }

  private buildStand() {
    const t = this.track, i0 = t.wrap(-36), g = new THREE.Group();
    g.position.copy(t.point(i0, WALL_OFF + 9)); g.rotation.y = t.heading(i0);
    const crowd = canvasTexture(512, 64, c => {
      c.fillStyle = '#2a2d3a'; c.fillRect(0, 0, 512, 64);
      const cols = ['#ff2d3d', '#ffd23f', '#2f7bff', '#22c55e', '#ffffff', '#c03bf0', '#ff8a1a'];
      for (let i = 0; i < 520; i++) { c.fillStyle = cols[i % cols.length]; c.beginPath(); c.arc(Math.random() * 512, 10 + Math.random() * 46, 3.2, 0, 7); c.fill(); }
    });
    const crowdMat = new THREE.MeshLambertMaterial({ map: crowd }), side = new THREE.MeshLambertMaterial({ color: lin('#d7dbe6') }), roof = new THREE.MeshLambertMaterial({ color: lin('#ff2d3d') });
    this.trash.push(crowd, crowdMat, side, roof);
    for (let s = 0; s < 4; s++) this.box(g, 3, 2, 46, [crowdMat, side, side, side, side, side], -s * 3, 1 + s * 2);
    this.box(g, 14, 0.5, 48, roof, -4.5, 12).rotation.z = 0.12;
    this.group.add(g);
  }

  private buildFlags() {
    const t = this.track, every = 30, n = Math.floor(t.N / every) * 2;
    const poles = this.add(new THREE.InstancedMesh(new THREE.CylinderGeometry(0.08, 0.08, 6, 5), new THREE.MeshLambertMaterial({ color: lin('#e5e7eb') }), n));
    const fg = new THREE.BufferGeometry();
    fg.setAttribute('position', new THREE.BufferAttribute(new Float32Array([0, 0, 0, 0, -1.4, 0, 0, -0.7, 2.2]), 3));
    fg.computeVertexNormals();
    const flags = this.add(new THREE.InstancedMesh(fg, new THREE.MeshLambertMaterial({ color: '#ffffff', side: THREE.DoubleSide }), n));
    const cols = ['#ff2d3d', '#ffd23f', '#2f7bff', '#22c55e', '#c03bf0'];
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), c = new THREE.Color(), one = new THREE.Vector3(1, 1, 1), up = new THREE.Vector3(0, 1, 0);
    let k = 0;
    for (let i = 12; i < t.N; i += every) for (const s of [-1, 1]) {
      if (k >= n) break;
      const p = t.point(i, s * (WALL_OFF + 1.2));
      poles.setMatrixAt(k, m4.compose(p.clone().setY(3), q.identity(), one));
      flags.setMatrixAt(k, m4.compose(p.setY(5.9), q.setFromAxisAngle(up, t.heading(i) + Math.PI), one));
      flags.setColorAt(k, c.set(cols[k % cols.length]).convertSRGBToLinear());
      k++;
    }
    poles.count = k; flags.count = k;
  }

  update(time: number, cam: THREE.Camera) {
    this.sky.position.copy(cam.position);
    for (let i = 0; i < this.clouds.length; i++) this.clouds[i].position.x += Math.sin(time * 0.05 + i) * 0.02;
  }

  dispose() { this.trash.forEach(t => t.dispose()); this.trash = []; this.group.clear(); }
}

import * as THREE from 'three';

// r170 trae gestión de color y r128 no: la desactivamos y linealizamos a mano con lin() → mismo resultado en ambas.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;
/** Color sRGB (#hex) → lineal para materiales, luces, niebla e instancias. */
export const lin = (c: string | THREE.Color) => new THREE.Color(c).convertSRGBToLinear();

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Color hex → vector sRGB "crudo" para shaders propios (igual en r128 y r170). */
export function rawColor(hex: string) {
  const v = parseInt(hex.replace('#', ''), 16);
  return new THREE.Vector3(((v >> 16) & 255) / 255, ((v >> 8) & 255) / 255, (v & 255) / 255);
}

/** Textura desde un canvas 2D dibujado al vuelo. */
export function canvasTexture(w: number, h: number, draw: (g: CanvasRenderingContext2D) => void, repeat = false) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const g = c.getContext('2d')!;
  draw(g);
  const t = new THREE.CanvasTexture(c);
  if (repeat) { t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping; }
  t.anisotropy = 4;
  return srgbTexture(t);
}

/** Degradado radial (halos, sombras, llamas). */
export function radialTexture(stops: Array<[number, string]>, size = 64) {
  return canvasTexture(size, size, g => {
    const h = size / 2, gr = g.createRadialGradient(h, h, 0, h, h, h);
    stops.forEach(([o, c]) => gr.addColorStop(o, c));
    g.fillStyle = gr; g.fillRect(0, 0, size, size);
  });
}

// Circuito procedural: spline cerrada (Catmull-Rom) muestreada + asfalto, pianos, escapatoria y muros.
import * as THREE from 'three';
import { Theme } from './config';
import { canvasTexture } from './three-compat';

export const ROAD_W = 16;
export const CURB_W = 1.6;
export const WALL_OFF = ROAD_W / 2 + 6;

export function mulberry(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface Nearest { idx: number; lat: number; along: number }

export class Track {
  readonly N = 900; readonly length: number; readonly radius: number; readonly center = new THREE.Vector2();
  readonly px: Float32Array; readonly pz: Float32Array; readonly tx: Float32Array; readonly tz: Float32Array;
  readonly dist: Float32Array; readonly curv: Float32Array; readonly group = new THREE.Group();
  private trash: Array<{ dispose(): void }> = [];

  constructor(readonly theme: Theme) {
    const rnd = mulberry(theme.seed * 977 + 13), n = 11, pts: THREE.Vector3[] = [];
    const p1 = rnd() * 6.28, p2 = rnd() * 6.28, p3 = rnd() * 6.28;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + (rnd() - 0.5) * 0.18;
      const r = 150 * (0.78 + 0.2 * Math.sin(2 * a + p1) + 0.12 * Math.sin(3 * a + p2) + 0.06 * Math.sin(5 * a + p3)) + rnd() * 14;
      pts.push(new THREE.Vector3(Math.cos(a) * r * 1.25, 0, Math.sin(a) * r));
    }
    const N = this.N, sp = new THREE.CatmullRomCurve3(pts, true, 'centripetal').getSpacedPoints(N);
    this.px = new Float32Array(N); this.pz = new Float32Array(N); this.tx = new Float32Array(N); this.tz = new Float32Array(N);
    this.dist = new Float32Array(N + 1); this.curv = new Float32Array(N);
    for (let i = 0; i < N; i++) { this.px[i] = sp[i].x; this.pz[i] = sp[i].z; }
    let d = 0, cx = 0, cz = 0, rmax = 0;
    for (let i = 0; i < N; i++) {
      const a = (i + N - 1) % N, b = (i + 1) % N, dx = this.px[b] - this.px[a], dz = this.pz[b] - this.pz[a], l = Math.hypot(dx, dz) || 1;
      this.tx[i] = dx / l; this.tz[i] = dz / l; this.dist[i] = d;
      d += Math.hypot(this.px[b] - this.px[i], this.pz[b] - this.pz[i]); cx += this.px[i]; cz += this.pz[i];
    }
    this.dist[N] = d; this.length = d; this.center.set(cx / N, cz / N);
    for (let i = 0; i < N; i++) {
      rmax = Math.max(rmax, Math.hypot(this.px[i] - this.center.x, this.pz[i] - this.center.y));
      const j = (i + 28) % N;
      this.curv[i] = Math.acos(THREE.MathUtils.clamp(this.tx[i] * this.tx[j] + this.tz[i] * this.tz[j], -1, 1));
    }
    this.radius = rmax; this.buildSurface();
  }

  wrap(i: number) { const k = Math.round(i) % this.N; return k < 0 ? k + this.N : k; }
  /** Vector derecho (perpendicular a la tangente en el plano XZ). */
  rx(i: number) { return -this.tz[i]; }
  rz(i: number) { return this.tx[i]; }

  /** Punto del circuito en el índice i con desplazamiento lateral. */
  point(i: number, lat = 0, out = new THREE.Vector3()) {
    const k = this.wrap(i);
    return out.set(this.px[k] + this.rx(k) * lat, 0, this.pz[k] + this.rz(k) * lat);
  }
  heading(i: number) { const k = this.wrap(i); return Math.atan2(this.tx[k], this.tz[k]); }

  /** Búsqueda local de la muestra más cercana a partir de una pista (hint). */
  nearest(x: number, z: number, hint: number, win = 24): Nearest {
    let best = hint, bd = Infinity;
    for (let o = -win; o <= win; o++) {
      const k = this.wrap(hint + o);
      const dx = x - this.px[k], dz = z - this.pz[k];
      const dd = dx * dx + dz * dz;
      if (dd < bd) { bd = dd; best = k; }
    }
    const dx = x - this.px[best], dz = z - this.pz[best];
    return { idx: best, lat: dx * this.rx(best) + dz * this.rz(best), along: this.dist[best] + dx * this.tx[best] + dz * this.tz[best] };
  }
  /** Búsqueda global (para colocar escenario). */
  nearestGlobal(x: number, z: number, step = 6) {
    let best = 0, bd = Infinity;
    for (let k = 0; k < this.N; k += step) { const dd = (x - this.px[k]) ** 2 + (z - this.pz[k]) ** 2; if (dd < bd) { bd = dd; best = k; } }
    return { idx: best, d: Math.sqrt(bd) };
  }

  private ribbon(a: number, b: number, ya: number, yb: number, vLen: number, mat: THREE.Material) {
    const N = this.N, pos = new Float32Array((N + 1) * 6), uv = new Float32Array((N + 1) * 4), idx: number[] = [];
    for (let i = 0; i <= N; i++) {
      const k = i % N, rx = this.rx(k), rz = this.rz(k), v = this.dist[i] / vLen;
      pos.set([this.px[k] + rx * a, ya, this.pz[k] + rz * a, this.px[k] + rx * b, yb, this.pz[k] + rz * b], i * 6);
      uv.set([0, v, 1, v], i * 4);
      if (i < N) { const o = i * 2; idx.push(o, o + 1, o + 2, o + 1, o + 3, o + 2); }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    g.setIndex(idx); g.computeVertexNormals();
    this.group.add(new THREE.Mesh(g, mat)); this.trash.push(g);
  }

  private mat(map: THREE.Texture, extra: THREE.MeshLambertMaterialParameters = {}) {
    const m = new THREE.MeshLambertMaterial({ map, ...extra });
    this.trash.push(m, map);
    return m;
  }

  private buildSurface() {
    const th = this.theme, W = ROAD_W, E = W / 2 + CURB_W;
    const speckle = (g: CanvasRenderingContext2D, n: number, size: number, a: string, b: string) => {
      for (let i = 0; i < n; i++) { g.fillStyle = Math.random() < 0.5 ? a : b; g.fillRect(Math.random() * size, Math.random() * size, 2, 2); }
    };
    this.ribbon(-W / 2, W / 2, 0.03, 0.03, 14, this.mat(canvasTexture(256, 256, g => {
      g.fillStyle = '#4b4f5c'; g.fillRect(0, 0, 256, 256);
      speckle(g, 2600, 256, 'rgba(70,72,84,0.6)', 'rgba(100,102,112,0.6)');
      g.fillStyle = '#f4f4f4'; g.fillRect(6, 0, 6, 256); g.fillRect(244, 0, 6, 256);
      g.fillStyle = 'rgba(255,255,255,0.75)'; g.fillRect(125, 0, 6, 120);
      g.fillStyle = 'rgba(20,20,26,0.25)'; g.fillRect(60, 0, 26, 256); g.fillRect(170, 0, 26, 256);
    }, true)));
    // Pianos rojiblancos (o del color del tema)
    const curbMat = this.mat(canvasTexture(32, 64, g => { g.fillStyle = th.curb[0]; g.fillRect(0, 0, 32, 32); g.fillStyle = th.curb[1]; g.fillRect(0, 32, 32, 32); }, true));
    this.ribbon(-E, -W / 2, 0.08, 0.05, 3.2, curbMat); this.ribbon(W / 2, E, 0.05, 0.08, 3.2, curbMat);
    // Escapatoria de grava
    const gravMat = this.mat(canvasTexture(128, 128, g => { g.fillStyle = th.runoff; g.fillRect(0, 0, 128, 128); speckle(g, 900, 128, 'rgba(0,0,0,0.10)', 'rgba(255,255,255,0.18)'); }, true));
    this.ribbon(-WALL_OFF, -E, 0.02, 0.02, 6, gravMat); this.ribbon(E, WALL_OFF, 0.02, 0.02, 6, gravMat);
    // Muros con publicidad
    const wallMat = this.mat(canvasTexture(512, 64, g => {
      g.fillStyle = th.wall[0]; g.fillRect(0, 0, 512, 64); g.fillStyle = th.wall[1]; g.fillRect(256, 0, 256, 64);
      g.font = 'italic 900 40px Arial'; g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillStyle = th.wall[1]; g.fillText('KART RALLY', 128, 34); g.fillStyle = th.wall[0]; g.fillText('¡A TOPE!', 384, 34);
      g.fillStyle = 'rgba(0,0,0,0.25)'; g.fillRect(0, 56, 512, 8);
    }, true), { side: THREE.DoubleSide });
    this.ribbon(-WALL_OFF, -WALL_OFF, 0, 1.3, 16, wallMat); this.ribbon(WALL_OFF, WALL_OFF, 1.3, 0, 16, wallMat);
    // Línea de salida/meta a cuadros
    const checker = canvasTexture(128, 32, g => { for (let x = 0; x < 16; x++) for (let y = 0; y < 4; y++) { g.fillStyle = (x + y) % 2 ? '#111' : '#fff'; g.fillRect(x * 8, y * 8, 8, 8); } });
    const line = new THREE.Mesh(new THREE.PlaneGeometry(W, 2.4), this.mat(checker));
    line.rotation.set(-Math.PI / 2, this.heading(0), 0, 'YXZ'); line.position.set(this.px[0], 0.06, this.pz[0]);
    this.trash.push(line.geometry); this.group.add(line);
  }

  /** Lista de puntos 2D normalizados (0..1) para el minimapa. */
  minimapPoints(step = 6) {
    const r = this.radius * 1.05, out: Array<[number, number]> = [];
    for (let i = 0; i < this.N; i += step) out.push([(this.px[i] - this.center.x) / r * 0.5 + 0.5, (this.pz[i] - this.center.y) / r * 0.5 + 0.5]);
    return out;
  }

  dispose() { this.trash.forEach(t => t.dispose()); this.trash = []; this.group.clear(); }
}

.kr-root { font-family: 'Trebuchet MS', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; user-select: none; -webkit-user-select: none; touch-action: none; color: #141a33; }

.kr-title {
  font-style: italic; font-weight: 900; line-height: 0.9; letter-spacing: -0.01em; color: #ffd23f;
  -webkit-text-stroke: 3px #141a33; paint-order: stroke fill;
  text-shadow: 0 6px 0 #141a33, 0 10px 24px rgba(20, 26, 51, 0.45);
}
.kr-title .kr-red, .kr-title.kr-red { color: #ff2d3d; }
.kr-num { font-style: italic; font-weight: 900; color: #fff; -webkit-text-stroke: 2px #141a33; paint-order: stroke fill; text-shadow: 0 4px 0 #141a33; }

.kr-panel { background: rgba(255, 255, 255, 0.92); border: 3px solid #141a33; border-radius: 18px; box-shadow: 0 6px 0 #141a33, 0 14px 30px rgba(20, 26, 51, 0.25); }
.kr-dark { background: rgba(20, 26, 51, 0.82); border: 2px solid rgba(255, 255, 255, 0.85); border-radius: 16px; color: #fff; box-shadow: 0 5px 0 rgba(20, 26, 51, 0.9); }

.kr-btn { border: 3px solid #141a33; border-radius: 16px; box-shadow: 0 5px 0 #141a33; font-weight: 900; font-style: italic; transition: transform 0.08s, box-shadow 0.08s, filter 0.15s; }
.kr-btn:hover { filter: brightness(1.07); }
.kr-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 #141a33; }

.kr-checker { background-image: conic-gradient(#141a33 25%, #fff 0 50%, #141a33 0 75%, #fff 0); background-size: 16px 16px; }
.kr-vignette { pointer-events: none; background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0) 55%, rgba(10, 14, 30, 0.35) 100%); }

@keyframes kr-pop { 0% { transform: scale(2.2); opacity: 0; } 30% { transform: scale(0.92); opacity: 1; } 45% { transform: scale(1.05); } 100% { transform: scale(1); opacity: 1; } }
.kr-pop { animation: kr-pop 0.55s cubic-bezier(0.2, 0.9, 0.3, 1.2) both; }
@keyframes kr-toast { 0% { transform: translateY(14px) scale(0.8); opacity: 0; } 15% { transform: translateY(0) scale(1.06); opacity: 1; } 80% { opacity: 1; } 100% { transform: translateY(-16px); opacity: 0; } }
.kr-toast { animation: kr-toast 1.4s ease-out both; }
@keyframes kr-blink { 50% { opacity: 0.25; } }
.kr-blink { animation: kr-blink 0.5s steps(2) infinite; }
@keyframes kr-float { 50% { transform: translateY(-6px) rotate(-2deg); } }
.kr-float { animation: kr-float 3s ease-in-out infinite; }
